        'conflict-resolution-and-adaptability' => ['en' => 'Conflict Resolution and Adaptability', 'ar' => 'إدارة النزاعات والقدرة على التكيف', 'days' => 3, 'summary' => ['en' => 'Many individuals view conflict as something to be avoided at any cost, leading them to withdraw from situations where they should be asserting control rather than stepping back from critical issues.', 'ar' => 'ينظر كثير من الأفراد إلى النزاع على أنه أمر يجب تجنّبه بأي ثمن، مما يدفعهم إلى الانسحاب من مواقف كان ينبغي لهم فيها أن يمسكوا بزمام الأمور بدلاً من التراجع أمام القضايا الحاسمة.']],
        'win-win-negotiation-skills' => ['en' => 'Win-Win Negotiation Skills', 'ar' => 'مهارات التفاوض الناجح (ربح - ربح)', 'days' => 3, 'summary' => ['en' => 'Negotiation is an integral aspect of our daily interactions.', 'ar' => 'التفاوض جزء لا يتجزأ من تعاملاتنا اليومية؛ فنحن نخوض المفاوضات بانتظام سواء مع العملاء أو الموردين أو الزملاء أو شركاء العمل أو أفراد الأسرة.']],
        'learning-through-adaptability' => ['en' => 'Learning through adaptability', 'ar' => 'تنمية مهارات التكيف مع أجواء العمل', 'days' => 3, 'summary' => ['en' => 'The crucial element for success and satisfaction in both life and business lies in the ability to learn.', 'ar' => 'يكمن العنصر الحاسم للنجاح والرضا في الحياة والعمل على حدّ سواء في القدرة على التعلّم.']],
