        'adaptive-leadership-skills' => ['en' => 'Adaptive Leadership Skills', 'ar' => 'مهارات القيادة المتكيفة', 'days' => 3, 'summary' => ['en' => 'This course is designed to equip participants with the essential skills needed to help their organizations thrive in an ever-changing world.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات الأساسية اللازمة لمساعدة مؤسساتهم على الازدهار في عالم دائم التغير.']],
        'empowering-the-workplace-for-greater-impact' => ['en' => 'Empowering the Workplace for Greater Impact', 'ar' => 'تعزيز مفهوم التمكين في بيئة العمل', 'days' => 3, 'summary' => ['en' => 'In today’s business environment, empowerment is increasingly recognized as a key driver for boosting employee productivity and engagement.', 'ar' => 'في بيئة الأعمال الحالية، يحظى التمكين باعتراف متزايد بوصفه محركاً رئيسياً لتعزيز إنتاجية الموظفين وارتباطهم الوظيفي.']],
        'managing-up-down-and-across' => ['en' => 'Managing Up, Down and Across', 'ar' => 'الإدارة الإفقية والعمودية والتعامل مع مختلف المستويات الإدارية', 'days' => 3, 'summary' => ['en' => 'Transitioning into a managerial or supervisory role presents new challenges and responsibilities.', 'ar' => 'ينطوي الانتقال إلى دور إداري أو إشرافي على تحديات ومسؤوليات جديدة.']],
        'the-power-of-leaders' => ['en' => 'The Power of Leaders', 'ar' => 'القائد المتميز', 'days' => 3, 'summary' => ['en' => 'This course explores the fundamental distinctions between management and leadership, offering participants a comprehensive understanding of emotional intelligence and its role in effective leadership.', 'ar' => 'تستكشف هذه الدورة الفروق الجوهرية بين الإدارة والقيادة، وتقدم للمشاركين فهماً شاملاً للذكاء العاطفي ودوره في القيادة الفعالة.']],
        'middle-management-skills' => ['en' => 'Middle Management Skills', 'ar' => 'مهارات الإدارة الوسطى', 'days' => 3, 'summary' => ['en' => 'Developing strong managerial and leadership skills is essential for driving personal and organizational success.', 'ar' => 'يُعدّ تطوير مهارات إدارية وقيادية قوية أمراً أساسياً لتحقيق النجاح على المستويين الشخصي والمؤسسي.']],
        'lean-six-sigma-green-belt' => ['en' => 'Lean Six Sigma Green Belt', 'ar' => 'دورة الحزام الأخضر المعتمدة من سداسية سيجما', 'days' => 5, 'summary' => ['en' => 'This unique Green Belt Six Sigma course will help you to improve the quality of your organization\'s operations by adopting a data-driven approach and provide you with the skills necessary to work on projects to benefit all types of processes and businesses.', 'ar' => 'ستساعدك هذه الدورة المتميزة في الحزام الأخضر لمنهجية ستة سيجما (Six Sigma Green Belt) على تحسين جودة عمليات مؤسستك من خلال تبنّي نهج قائم على البيانات، كما ستزوّدك بالمهارات اللازمة للعمل على مشاريع تعود بالفائدة على جميع أنواع العمليات والأعمال.']],
        'coaching-and-mentoring-skills-for-managers' => ['en' => 'Coaching and Mentoring Skills for Managers', 'ar' => 'مهارات التوجيه والإرشاد الإداري للمدراء', 'days' => 3, 'summary' => ['en' => 'Managers often face significant challenges related to people performance, regardless of their experience level.', 'ar' => 'كثيراً ما يواجه المديرون تحديات كبيرة تتعلق بأداء الأفراد، بصرف النظر عن مستوى خبرتهم، إذ يتوقف النجاح على تعزيز الفاعلية من خلال الآخرين.']],
        'business-decision-models' => ['en' => 'Business Decision Models', 'ar' => 'نماذج إتخاذ القرارت في الأعمال الناجحة', 'days' => 5, 'summary' => ['en' => 'Managers frequently make decisions under conditions of certainty, risk, and uncertainty, yet many lack formal training in decision-making.', 'ar' => 'كثيراً ما يتخذ المديرون قرارات في ظل ظروف من اليقين والمخاطرة وعدم اليقين، ومع ذلك يفتقر كثير منهم إلى التدريب الرسمي في مجال اتخاذ القرارات.']],
        'leading-a-team-of-champions' => ['en' => 'Leading a Team of Champions', 'ar' => 'قيادة فريق من الأبطال', 'days' => 3, 'summary' => ['en' => 'This course is designed to equip leaders with the mindset and practical tools needed to unlock the full potential of their team members.', 'ar' => 'صُممت هذه الدورة لتزويد القادة بالعقلية والأدوات العملية اللازمة لإطلاق الإمكانات الكاملة لأعضاء فرقهم.']],
        'results-based-leadership' => ['en' => 'Results Based Leadership', 'ar' => 'القيادة المبنية على النتائج', 'days' => 3, 'summary' => ['en' => 'This course is designed to equip participants with the knowledge, skills, and competencies necessary to become effective results-based leaders.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف والمهارات والكفاءات اللازمة ليصبحوا قادة فاعلين قائمين على النتائج.']],
        'managing-multiple-tasks-priorities-and-deadlines' => ['en' => 'Managing Multiple Tasks, Priorities & Deadlines', 'ar' => 'إدارة المهام المتعددة', 'days' => 3, 'summary' => ['en' => 'Realizing visions and goals involves comprehending tasks, setting priorities, and establishing well-defined deadlines.', 'ar' => 'يتطلب تحقيق الرؤى والأهداف فهم المهام، وتحديد الأولويات، ووضع مواعيد نهائية محددة بوضوح.']],
        'transformational-change-and-strategic-leadership' => ['en' => 'Transformational Change & Strategic Leadership', 'ar' => 'القيادة الاستراتيجية وإدارة التغيير', 'days' => 5, 'summary' => ['en' => 'In today’s rapidly evolving business landscape, companies and industries are experiencing profound changes in their operations and customer service models.', 'ar' => 'في ظل بيئة الأعمال سريعة التطور اليوم، تشهد الشركات والقطاعات تغيّرات جذرية في عملياتها ونماذج خدمة عملائها.']],
        'human-behavior-analysis-and-micro-expression' => ['en' => 'Human Behavior Analysis & Micro-Expression', 'ar' => 'مهارات تحليل السلوك البشري وقراءة تعابير الوجه الدقيقة', 'days' => 5],
        'communication-and-relationship-management' => ['en' => 'Communication and Relationship Management', 'ar' => 'إدارة التواصل الفعال والعلاقات المهنية', 'days' => 3, 'summary' => ['en' => 'Exceptional communication and relationship management skills are essential for the success of any organization.', 'ar' => 'تُعد مهارات التواصل وإدارة العلاقات المتميزة ضرورية لنجاح أي مؤسسة، فهذه الكفاءات الأساسية هي الركيزة التي تقوم عليها الشركات المزدهرة والقادرة على الصمود.']],
        'performance-management' => ['en' => 'Performance Management', 'ar' => 'إدارة الأداء', 'days' => 3, 'summary' => ['en' => 'Front-line managers play a pivotal role in any performance management system, which extends beyond merely setting objectives and conducting appraisals.', 'ar' => 'يؤدي المديرون المباشرون دوراً محورياً في أي نظام لإدارة الأداء، وهو نظام يتجاوز مجرد تحديد الأهداف وإجراء التقييمات.']],
        'leading-and-managing-change' => ['en' => 'Leading and Managing Change', 'ar' => 'إدارة وقيادة التغيير', 'days' => 3, 'summary' => ['en' => 'This course serves as an ideal introduction for participants and the organizations they represent to the essential topics of change and change management.', 'ar' => 'تمثل هذه الدورة مدخلاً مثالياً للمشاركين والمؤسسات التي يمثلونها إلى الموضوعات الأساسية المتعلقة بالتغيير وإدارة التغيير.']],
        'key-managerial-skills-for-new-managers' => ['en' => 'Key Managerial Skills for New Managers', 'ar' => 'المهارات الإدارية الأساسية للمدراء الجدد', 'days' => 5, 'summary' => ['en' => 'In today’s dynamic and multifaceted work environment, stepping into a supervisory or managerial role requires acquiring new skills and adopting innovative approaches to achieve goals.', 'ar' => 'في بيئة العمل الديناميكية ومتعددة الجوانب اليوم، يتطلّب تولّي دور إشرافي أو إداري اكتساب مهارات جديدة واعتماد مناهج مبتكرة لتحقيق الأهداف.']],
        'leading-and-managing-breakthrough-innovation' => ['en' => 'Leading and Managing Breakthrough Innovation', 'ar' => 'القيادة الإبداعية والإبتكارية', 'days' => 3],
