        'leading-with-agility-and-resilience' => ['en' => 'Leading with Agility and Resilience', 'ar' => 'مهارات القيادة المرنة والرشيقة', 'days' => 3, 'summary' => ['en' => 'In today\'s fast-paced business landscape, organizations must continuously reinvent themselves to stay competitive and leverage emerging market trends.', 'ar' => 'في ظل بيئة الأعمال المتسارعة اليوم، يتعيّن على المؤسسات أن تعيد ابتكار نفسها باستمرار للحفاظ على قدرتها التنافسية والاستفادة من الاتجاهات الناشئة في السوق.']],
        'simplification-of-work-processes-and-procedures' => ['en' => 'Simplification of Work Processes and Procedures', 'ar' => 'تبسيط الإجراءات وخطوات العمل', 'days' => 3, 'summary' => ['en' => 'This dynamic course is centered around the theme of "Going back to basics," helping participants recognize the importance of simplifying organizational processes and procedures.', 'ar' => 'تتمحور هذه الدورة الديناميكية حول شعار "العودة إلى الأساسيات"، إذ تساعد المشاركين على إدراك أهمية تبسيط العمليات والإجراءات المؤسسية.']],
        'organizational-leadership' => ['en' => 'Organizational Leadership', 'ar' => 'التميز في القيادة المؤسسية', 'days' => 3, 'summary' => ['en' => 'The success of any organization is deeply influenced by its leadership.', 'ar' => 'يتأثر نجاح أي مؤسسة تأثراً عميقاً بقيادتها.']],
