        'strategic-thinking-and-planning' => ['en' => 'Strategic Thinking and Planning', 'ar' => 'التفكير والتخطيط الاستراتيجي', 'days' => 5, 'summary' => ['en' => 'An organization without a clear strategy is like a ship adrift without a rudder.', 'ar' => 'المؤسسة التي تفتقر إلى استراتيجية واضحة أشبه بسفينة تائهة بلا دفّة.']],
        'developing-and-implementing-the-business-plan' => ['en' => 'Developing and Implementing the Business Plan', 'ar' => 'تطوير وتنفيذ خطط العمل', 'days' => 3, 'summary' => ['en' => 'This course offers a practical, step-by-step approach to creating and executing business plans.', 'ar' => 'تقدّم هذه الدورة نهجاً عملياً متدرّجاً لإعداد خطط الأعمال وتنفيذها.']],
        'strategic-planning-from-planning-to-execution' => ['en' => 'Strategic Planning From Planning to Execution', 'ar' => 'التخطيط الاستراتيجي: من التخطيط الى التنفيذ', 'days' => 5],
