        'crisis-management' => ['en' => 'Crisis Management', 'ar' => 'استراتيجيات إدارة الأزمات', 'days' => 5, 'summary' => ['en' => 'This course equips participants with practical crisis management strategies and solutions, focusing on the effective implementation of Crisis Command, Control, Communications, and Intelligence (C3i), along with stakeholder management.', 'ar' => 'تزوّد هذه الدورة المشاركين باستراتيجيات وحلول عملية لإدارة الأزمات، مع التركيز على التطبيق الفعّال لمنظومة القيادة والسيطرة والاتصالات والاستخبارات في الأزمات (C3i)، إلى جانب إدارة أصحاب المصلحة.']],
        'managing-strategic-reviews' => ['en' => 'Managing Strategic Reviews', 'ar' => 'إدارة تقييم الاستراتيجيات', 'days' => 3, 'summary' => ['en' => 'Business reviews—whether conducted monthly, quarterly, annually, internally, externally, departmentally, or organization-wide—can vary significantly in their effectiveness.', 'ar' => 'تتفاوت مراجعات الأعمال تفاوتاً كبيراً في مدى فاعليتها، سواء أُجريت شهرياً أو ربع سنوياً أو سنوياً، وسواء كانت داخلية أو خارجية، على مستوى الإدارات أو على مستوى المؤسسة ككل.']],
        'strategic-decision-making-in-competitive-environments' => ['en' => 'Strategic Decision Making in Competitive Environments', 'ar' => 'مهارات اتخاذ القرارات الاستراتيجية في بيئات تنافسية', 'days' => 3],
