        'setting-key-performance-indicators-kpis' => ['en' => 'Setting Key Performance Indicators (KPIs)', 'ar' => 'استراتيجيات وضع مؤشرات الأداء القياسية', 'days' => 3, 'summary' => ['en' => 'This course delves into the essential world of Key Performance Indicators (KPIs), exploring their various types, applications, and significance in different areas of business.', 'ar' => 'تتعمق هذه الدورة في عالم مؤشرات الأداء الرئيسية (KPIs) الأساسي، مستكشفةً أنواعها المختلفة وتطبيقاتها وأهميتها في مختلف مجالات الأعمال.']],
        'the-balanced-scorecard-achieving-performance-excellence' => ['en' => 'The Balanced Scorecard: Achieving Performance Excellence', 'ar' => 'تحقيق التميز من خلال بطاقة الأداء المتوازن', 'days' => 3, 'summary' => ['en' => 'The Balanced Scorecard, developed by Dr.', 'ar' => 'تُعدّ بطاقة الأداء المتوازن، التي طوّرها الدكتور روبرت كابلان (كلية هارفارد للأعمال) والدكتور ديفيد نورتون، أداةً فعّالة لمواءمة أنشطة الأعمال مع رؤية المؤسسة واستراتيجيتها.']],
        'analytical-and-structured-thinking' => ['en' => 'Analytical and Structured Thinking', 'ar' => 'مهارات التفكير التحليلي والمنظم', 'days' => 3, 'summary' => ['en' => 'In today\'s intricate business environment, possessing strong analytical skills is vital for professionals aiming to contribute strategic value to their organizations.', 'ar' => 'في بيئة الأعمال المعقدة اليوم، يُعدّ امتلاك مهارات تحليلية قوية أمراً حيوياً للمهنيين الساعين إلى إضافة قيمة استراتيجية لمؤسساتهم.']],
        'feasibility-studies-preparation-analysis-and-evaluation' => ['en' => 'Feasibility Studies: Preparation, Analysis and Evaluation', 'ar' => 'إعداد وتحليل وتقييم دراسات الجدوى', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential skills needed to prepare, analyze, and evaluate feasibility studies.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات الأساسية اللازمة لإعداد دراسات الجدوى وتحليلها وتقييمها.']],
        'strategy-management-in-the-public-sector' => ['en' => 'Strategy Management in the Public Sector', 'ar' => 'إدارة الاستراتيجية في القطاع العام', 'days' => 3, 'summary' => ['en' => 'This course delves into the critical role of national competitiveness and explores the strategy pyramid within the public sector.', 'ar' => 'تتعمق هذه الدورة في الدور المحوري للتنافسية الوطنية، وتستكشف هرم الاستراتيجية في القطاع الحكومي.']],
        'project-management-professional-pmp' => ['en' => 'Project Management Professional (PMP)', 'ar' => 'التحضير لشهادة مدير المشاريع المحترف', 'days' => 5, 'summary' => ['en' => 'This course is designed to prepare participants for the Project Management Professional (PMP) certification exam.', 'ar' => 'صُممت هذه الدورة لإعداد المشاركين لاجتياز اختبار شهادة محترف إدارة المشاريع (PMP).']],
        'risk-management-professional-rmp' => ['en' => 'Risk Management Professional (RMP)', 'ar' => 'التحضير لشهادة مدير مخاطر المشاريع المحترف', 'days' => 5, 'summary' => ['en' => 'This course is designed to prepare participants for the Risk Management Professional (RMP) certification.', 'ar' => 'صُممت هذه الدورة لإعداد المشاركين للحصول على شهادة محترف إدارة المخاطر (RMP).']],
        'business-continuity-management' => ['en' => 'Business Continuity Management', 'ar' => 'إدارة استمرارية الأعمال', 'days' => 5, 'summary' => ['en' => 'This course equips participants with practical solutions, strategies, and insights to implement an effective Business Continuity Management System (BCMS).', 'ar' => 'تزوّد هذه الدورة المشاركين بالحلول والاستراتيجيات والرؤى العملية اللازمة لتطبيق نظام فعّال لإدارة استمرارية الأعمال (BCMS).']],
        'agile-project-management' => ['en' => 'Agile Project Management', 'ar' => 'إدارة المشاريع الرشيقة Agile', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the skills necessary for managing knowledge-based projects using agile methodologies.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات اللازمة لإدارة المشاريع القائمة على المعرفة باستخدام المنهجيات الرشيقة (Agile).']],
        'managing-projects-using-the-prince2-approach' => ['en' => 'Managing Projects using The PRINCE2 Approach', 'ar' => 'إدارة المشاريع باستخدام نظام PRINCE 2', 'days' => 5, 'summary' => ['en' => 'This course aims to equip participants with a thorough understanding of PRINCE2 principles, methodologies, processes, and themes essential for successful project management.', 'ar' => 'تهدف هذه الدورة إلى تزويد المشاركين بفهم شامل لمبادئ PRINCE2 ومنهجياتها وعملياتها وموضوعاتها الأساسية لإدارة المشاريع بنجاح.']],
        'mastering-project-metrics-kpis-and-dashboards' => ['en' => 'Mastering Project Metrics, KPIs and Dashboards', 'ar' => 'إعداد تنظيم مقاييس نجاح المشاريع ومؤشرات الأداء', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential skills to design, implement, and manage project metrics and Key Performance Indicators (KPIs).', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات الأساسية لتصميم مقاييس المشاريع ومؤشرات الأداء الرئيسية (KPIs) وتطبيقها وإدارتها.']],
        'microsoft-project' => ['en' => 'Microsoft Project', 'ar' => 'Microsoft Project', 'days' => 5],
        'managing-it-projects-effectively' => ['en' => 'Managing IT Projects Effectively', 'ar' => 'الإدارة الفعالة لمشاريع تقنية المعلومات', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential knowledge and skills needed to effectively manage an Information Technology (IT) project from start to finish.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف والمهارات الأساسية اللازمة لإدارة مشروع تقنية المعلومات (IT) بفاعلية من البداية حتى النهاية.']],
