        'managing-project-portfolio' => ['en' => 'Managing Project Portfolio', 'ar' => 'إدارة ملفات محافظ المشاريع', 'days' => 3, 'summary' => ['en' => 'This course aims to equip participants with a comprehensive and practical methodology for building and managing a balanced project portfolio.', 'ar' => 'تهدف هذه الدورة إلى تزويد المشاركين بمنهجية شاملة وعملية لبناء محفظة مشاريع متوازنة وإدارتها.']],
        'process-management-mapping-and-improvement' => ['en' => 'Process Management: Mapping and Improvement', 'ar' => 'تخطيط وتحسين أداء إدارة العمليات', 'days' => 3, 'summary' => ['en' => 'The power of a well-crafted diagram cannot be overstated, especially when it comes to understanding and improving organizational processes.', 'ar' => 'لا يمكن المبالغة في تقدير قوة المخطط المُعدّ بإتقان، ولا سيما عندما يتعلق الأمر بفهم العمليات المؤسسية وتحسينها.']],
        'human-resources-management-hrm' => ['en' => 'Human Resources Management HRM', 'ar' => 'إدارة الموارد البشرية', 'days' => 5, 'summary' => ['en' => 'Course Overview: The "HR Management Course" is designed to equip participants with a comprehensive understanding of the key functions within a modern HR department, emphasizing the role of knowledge as a gateway to engagement.', 'ar' => 'نظرة عامة على الدورة: صُمّمت "دورة إدارة الموارد البشرية" لتزويد المشاركين بفهم شامل للوظائف الرئيسية في إدارة الموارد البشرية الحديثة، مع التركيز على دور المعرفة بوصفها بوابةً لتعزيز الارتباط الوظيفي.']],
        'leadership-skills-for-hr-managers' => ['en' => 'Leadership Skills for HR Managers', 'ar' => 'تنمية المهارات القيادية لمدراء الموارد البشرية', 'days' => 3, 'summary' => ['en' => 'Many organizations overlook HR when it comes to strategic decision-making, largely due to the perception that HR lacks the necessary skills and strategic value compared to other functions.', 'ar' => 'تتجاهل كثير من المؤسسات دور الموارد البشرية عند اتخاذ القرارات الاستراتيجية، ويرجع ذلك إلى حد كبير إلى تصور مفاده أن الموارد البشرية تفتقر إلى المهارات اللازمة والقيمة الاستراتيجية مقارنة بالوظائف الأخرى.']],
        'career-development-and-succession-planning' => ['en' => 'Career Development and Succession Planning', 'ar' => 'التطوير المهني وتخطيط التعاقب الوظيفي', 'days' => 3, 'summary' => ['en' => 'With 60% of organizations lacking a formal process for succession planning, this interactive course provides participants with cutting-edge methodologies and strategies for career development and succession planning.', 'ar' => 'في ظل افتقار 60% من المؤسسات إلى آلية رسمية لتخطيط التعاقب الوظيفي، تزوّد هذه الدورة التفاعلية المشاركين بأحدث المنهجيات والاستراتيجيات في مجال التطوير الوظيفي وتخطيط التعاقب الوظيفي.']],
        'talent-acquisition' => ['en' => 'Talent Acquisition', 'ar' => 'مهارات وأساسيات جذب المواهب', 'days' => 3, 'summary' => ['en' => 'Talent acquisition today mirrors modern marketing practices.', 'ar' => 'باتت عملية استقطاب المواهب في الوقت الحاضر تحاكي ممارسات التسويق الحديثة.']],
        'human-capital-planning' => ['en' => 'Human Capital Planning', 'ar' => 'تخطيط وتنمية رأس المال البشري', 'days' => 5, 'summary' => ['en' => 'Human capital professionals need to align their activities with the company’s strategic objectives, positioning HR as a true business partner.', 'ar' => 'يحتاج المتخصصون في رأس المال البشري إلى مواءمة أنشطتهم مع الأهداف الاستراتيجية للشركة، بما يرسّخ مكانة الموارد البشرية بوصفها شريكاً حقيقياً في الأعمال.']],
        'excel-skills-for-hr-and-admin-professionals' => ['en' => 'Excel Skills for HR and Admin Professionals', 'ar' => 'برنامج الإكسل لأخصائيي الموارد البشرية', 'days' => 5, 'summary' => ['en' => 'his course is designed to help HR and administration professionals save valuable time on daily tasks by mastering Excel.', 'ar' => 'صُمّمت هذه الدورة لمساعدة متخصصي الموارد البشرية والشؤون الإدارية على توفير وقت ثمين في المهام اليومية من خلال إتقان برنامج Excel.']],
        'train-the-trainer' => ['en' => 'Train the Trainer', 'ar' => 'تدريب المدربين', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip trainers with the essential knowledge and skills needed to create and deliver effective training sessions.', 'ar' => 'صُممت هذه الدورة لتزويد المدرّبين بالمعارف والمهارات الأساسية اللازمة لإعداد جلسات تدريبية فعّالة وتقديمها.']],
        'training-and-development-management' => ['en' => 'Training and Development Management', 'ar' => 'إدارة أقسام التدريب والتطوير', 'days' => 3, 'summary' => ['en' => 'Training and development professionals face ongoing pressure to deliver outstanding training services.', 'ar' => 'يواجه متخصصو التدريب والتطوير ضغوطاً مستمرة لتقديم خدمات تدريبية متميزة.']],
        'employee-relations-roles-and-responsibilities' => ['en' => 'Employee Relations: Roles and Responsibilities', 'ar' => 'أدوار ومسؤوليات أخصائيي قسم علاقات الموظفين', 'days' => 3, 'summary' => ['en' => 'Although the various functions within Human Resources (HR) have evolved, Employee Relations (ER) remains somewhat ambiguous.', 'ar' => 'على الرغم من تطور الوظائف المختلفة ضمن الموارد البشرية (HR)، لا تزال علاقات الموظفين (ER) تكتنفها بعض الضبابية.']],
        'compensation-and-benefits' => ['en' => 'Compensation and Benefits', 'ar' => 'نظام التعويضات والمزايا الوظيفية', 'days' => 3, 'summary' => ['en' => 'This course delves into one of the behind-the-scenes functions of human resources: Compensation and Benefits.', 'ar' => 'تتعمق هذه الدورة في إحدى وظائف الموارد البشرية التي تعمل خلف الكواليس، وهي التعويضات والمزايا.']],
