        'hr-business-partner-roles-responsibilities-and-competencies' => ['en' => 'HR Business Partner: Roles, Responsibilities and Competencies', 'ar' => 'أدوار ومسؤوليات شركاء الأعمال في الموارد البشرية', 'days' => 3, 'summary' => ['en' => 'The role of an HR Business Partner (HRBP) varies widely across organizations, often leading to confusion about its true purpose and responsibilities.', 'ar' => 'يتفاوت دور شريك أعمال الموارد البشرية (HRBP) تفاوتاً كبيراً بين المؤسسات، مما يؤدي غالباً إلى الالتباس بشأن غرضه الحقيقي ومسؤولياته.']],
        'learning-and-development-tools-and-strategies' => ['en' => 'Learning and Development: Tools and Strategies', 'ar' => 'استراتيجيات إدارة قسم التعليم والتطوير', 'days' => 3, 'summary' => ['en' => 'In today’s dynamic work environment, employees must continuously enhance their knowledge, skills, and abilities to stay effective and motivated.', 'ar' => 'في بيئة العمل الديناميكية اليوم، يتعين على الموظفين تعزيز معارفهم ومهاراتهم وقدراتهم باستمرار للحفاظ على فاعليتهم وحماسهم.']],
        'payroll-preparation-analysis-and-management' => ['en' => 'Payroll: Preparation, Analysis and Management', 'ar' => 'إدارة إعداد وتحليل الرواتب والمستحقات', 'days' => 3, 'summary' => ['en' => 'Payroll and employee benefits represent one of the most significant expenses for any organization, second only to the Cost of Goods Sold (COGS), rent, and depreciation.', 'ar' => 'تمثل الرواتب ومزايا الموظفين أحد أكبر المصروفات في أي مؤسسة، إذ لا يتقدم عليها سوى تكلفة البضاعة المباعة (COGS) والإيجار والإهلاك.']],
        'workforce-planning-and-budgeting' => ['en' => 'Workforce Planning and Budgeting', 'ar' => 'تخطيط القوى العاملة وإعداد الموازنات', 'days' => 3, 'summary' => ['en' => 'Workforce planning is a critical HR process, interconnected with every other HR function, yet it is often executed inconsistently due to organizational and market complexities.', 'ar' => 'يُعد تخطيط القوى العاملة عملية حيوية من عمليات الموارد البشرية، ترتبط بكل وظيفة أخرى من وظائفها، إلا أنها كثيراً ما تُنفّذ بصورة غير متسقة بسبب التعقيدات التنظيمية وتعقيدات السوق.']],
        'employee-on-boarding-induction-and-orientation' => ['en' => 'Employee On-Boarding: Induction & Orientation', 'ar' => 'تقنيات التعريف والإرشاد الوظيفي للموظفين الجدد', 'days' => 3, 'summary' => ['en' => 'The first few days of employment are crucial in shaping a new hire’s experience and long-term success within the organization.', 'ar' => 'تُعدّ الأيام الأولى من التوظيف حاسمةً في تشكيل تجربة الموظف الجديد ونجاحه على المدى الطويل داخل المؤسسة.']],
