        'branding-and-brand-management' => ['en' => 'Branding & Brand Management', 'ar' => 'إدارة العلامات التجارية والهوية البصرية', 'days' => 5, 'summary' => ['en' => 'Branding is the process that allows businesses to differentiate their products from competitors by creating a unique identity.', 'ar' => 'بناء العلامة التجارية هو العملية التي تتيح للشركات تمييز منتجاتها عن منتجات المنافسين من خلال إيجاد هوية فريدة.']],
        'marketing-communications-and-media-planning' => ['en' => 'Marketing Communications and Media Planning', 'ar' => 'تنمية مهارات التواصل والتخطيط الإعلامي لدى أخصائيي التسويق', 'days' => 5, 'summary' => ['en' => 'Marketing communications, including advertising, is the craft of developing and delivering messages that inform consumers about products, services, or ideas.', 'ar' => 'تمثل الاتصالات التسويقية، بما فيها الإعلان، فنّ إعداد الرسائل وإيصالها لتعريف المستهلكين بالمنتجات أو الخدمات أو الأفكار.']],
