        'core-marketing-and-sales-skills' => ['en' => 'Core Marketing and Sales Skills', 'ar' => 'تنمية مهارات المبيعات والتسويق الأساسية', 'days' => 3, 'summary' => ['en' => 'This course provides a comprehensive opportunity to refresh core marketing and sales practices, demonstrating how these two disciplines can work together to create synergy and provide a significant competitive edge in today\'s marketplace.', 'ar' => 'تتيح هذه الدورة فرصة شاملة لتجديد الممارسات الأساسية في التسويق والمبيعات، مع توضيح كيفية تكامل هذين المجالين لتحقيق التآزر وتوفير ميزة تنافسية كبيرة في أسواق اليوم.']],
        'advanced-digital-marketing' => ['en' => 'Advanced Digital Marketing', 'ar' => 'دورة متقدمة في التسويق الالكتروني', 'days' => 3, 'summary' => ['en' => 'The Advanced Digital Marketing course equips participants with in-depth knowledge and advanced strategies across key areas of digital marketing.', 'ar' => 'تزوّد دورة التسويق الرقمي المتقدم المشاركين بمعرفة معمّقة واستراتيجيات متقدمة في المجالات الرئيسية للتسويق الرقمي.']],
        'developing-purchasing-policies-and-processes' => ['en' => 'Developing Purchasing Policies & Processes', 'ar' => 'تطوير عمليات وسياسات إدارة المشتريات', 'days' => 5, 'summary' => ['en' => 'Purchasing policies, processes, and Service Level Agreements (SLAs) are crucial in guiding the work of purchasing professionals and their internal stakeholders.', 'ar' => 'تؤدي سياسات المشتريات وإجراءاتها واتفاقيات مستوى الخدمة (SLAs) دوراً محورياً في توجيه عمل مهنيي المشتريات وأصحاب المصلحة الداخليين لديهم، إذ توفر هذه الوثائق توجيهاً تشغيلياً وأخلاقياً في آن واحد.']],
        'procurement-planning-and-bid-management' => ['en' => 'Procurement Planning and Bid Management', 'ar' => 'تخطيط أقسام المشتريات وادارة المناقصات', 'days' => 5, 'summary' => ['en' => 'Effective procurement planning is essential for ensuring supply security while balancing the goals of cost savings and internal customer satisfaction.', 'ar' => 'يُعد التخطيط الفعال للمشتريات أمراً أساسياً لضمان أمن الإمدادات مع تحقيق التوازن بين هدفي خفض التكاليف ورضا العملاء الداخليين.']],
        'purchasing-management-and-cost-saving-techniques' => ['en' => 'Purchasing Management and Cost Saving Techniques', 'ar' => 'ادارة عمليات الشراء وتقنيات خفض التكلفة', 'days' => 3, 'summary' => ['en' => 'Managing a 21st-century purchasing department comes with its own set of challenges.', 'ar' => 'تنطوي إدارة قسم المشتريات في القرن الحادي والعشرين على مجموعة خاصة من التحديات.']],
        'the-successful-buyer' => ['en' => 'The Successful Buyer', 'ar' => 'المشتري الناجح', 'days' => 3, 'summary' => ['en' => 'What defines a successful buyer in today’s marketplace?', 'ar' => 'ما الذي يميز المشتري الناجح في سوق اليوم؟']],
        'negotiation-strategies-for-better-purchasing' => ['en' => 'Negotiation Strategies for Better Purchasing', 'ar' => 'استراتيجيات التفاوض لتحقيق أفضل قيمة شرائية', 'days' => 3, 'summary' => ['en' => 'Negotiation is a critical skill for any purchasing professional.', 'ar' => 'يُعد التفاوض مهارة بالغة الأهمية لأي متخصص في المشتريات.']],
        'leading-and-managing-vendor-relations' => ['en' => 'Leading and Managing Vendor Relations', 'ar' => 'المهارات القيادية والادارية لأخصائيي علاقات الموردين', 'days' => 3, 'summary' => ['en' => 'Strong vendor relationships are key to driving business success and profitability.', 'ar' => 'تُعدّ العلاقات القوية مع الموردين عاملاً رئيسياً في تحقيق نجاح الأعمال وربحيتها.']],
        'strategic-sourcing-techniques-for-better-procurement-value' => ['en' => 'Strategic Sourcing: Techniques for Better Procurement Value', 'ar' => 'تقنيات واستراتيجية التوريد لتحقيق أفضل قيمة لعمليات المشتريات', 'days' => 3, 'summary' => ['en' => 'Procurement is often treated as an administrative function, with sourcing decisions made at a distance.', 'ar' => 'غالباً ما يُعامَل الشراء بوصفه وظيفة إدارية، إذ تُتخذ قرارات التوريد بمعزل عن السياق.']],
        'managing-supply-and-demand' => ['en' => 'Managing Supply and Demand', 'ar' => 'إدارة عمليات العرض والطلب', 'days' => 3, 'summary' => ['en' => 'This course leverages Cesim’s ‘SimFirm’ simulation tool to replicate real-world competitive and operational decision-making scenarios faced by managers.', 'ar' => 'تعتمد هذه الدورة على أداة المحاكاة \'SimFirm\' من Cesim لمحاكاة سيناريوهات اتخاذ القرارات التنافسية والتشغيلية الواقعية التي يواجهها المديرون.']],
        'logistics-management' => ['en' => 'Logistics Management', 'ar' => 'إدارة الخدمات اللوجستية', 'days' => 3, 'summary' => ['en' => 'Logistics management is a critical function that oversees the flow of goods within a supply chain.', 'ar' => 'تُعدّ إدارة الخدمات اللوجستية وظيفة بالغة الأهمية تشرف على تدفق البضائع داخل سلسلة التوريد.']],
        'stock-management-forecasting-and-demand-planning' => ['en' => 'Stock Management, Forecasting and Demand Planning', 'ar' => 'إدارة المخزون وتخطيط الطلبات', 'days' => 3, 'summary' => ['en' => 'Effective demand planning and stock control are crucial for improving the accuracy of forecasts, maintaining optimal inventory levels, and enhancing profitability by managing expenses.', 'ar' => 'يُعدّ التخطيط الفعّال للطلب والتحكم في المخزون أمراً حاسماً لتحسين دقة التنبؤات، والحفاظ على مستويات مثلى من المخزون، وتعزيز الربحية من خلال إدارة النفقات.']],
        'warehouse-operations-and-management' => ['en' => 'Warehouse Operations and Management', 'ar' => 'إدارة المخازن والمستودعات', 'days' => 3, 'summary' => ['en' => 'Managing inventories that can total millions of dollars requires an efficient warehouse to store, maintain, and protect these valuable assets.', 'ar' => 'تتطلب إدارة المخزون الذي قد تبلغ قيمته ملايين الدولارات مستودعاً فعّالاً لتخزين هذه الأصول القيّمة وصيانتها وحمايتها.']],
        'supply-chain-operations-management' => ['en' => 'Supply Chain Operations Management', 'ar' => 'إدارة عمليات سلاسل التوريد', 'days' => 3, 'summary' => ['en' => 'Weak supply chains can disrupt the flow of goods and services, leading to increased costs and decreased customer satisfaction.', 'ar' => 'قد تؤدي سلاسل الإمداد الضعيفة إلى تعطيل تدفق السلع والخدمات، مما يفضي إلى ارتفاع التكاليف وتراجع رضا العملاء.']],
        'supply-chain-risk-management' => ['en' => 'Supply Chain Risk Management', 'ar' => 'إدارة مخاطر عمليات سلاسل التوريد', 'days' => 3, 'summary' => ['en' => 'Effectively managing risks within a supply chain is an essential skill for any supply chain professional today.', 'ar' => 'تُعد الإدارة الفعّالة للمخاطر في سلسلة الإمداد مهارة أساسية لأي متخصص في سلاسل الإمداد في الوقت الراهن.']],
