        'certified-public-relations-professional' => ['en' => 'Certified Public Relations Professional', 'ar' => 'شهادة أخصائي العلاقات العامة المعتمد', 'days' => 5, 'summary' => ['en' => 'This course provides a comprehensive, step-by-step approach to Public Relations (PR) planning and management.', 'ar' => 'تقدم هذه الدورة منهجاً شاملاً ومتدرجاً لتخطيط العلاقات العامة (PR) وإدارتها.']],
        'events-and-conferences-management' => ['en' => 'Events and Conferences Management', 'ar' => 'إدارة الفعاليات والمؤتمرات', 'days' => 5, 'summary' => ['en' => 'This course offers essential principles and practices for individuals involved in planning and organizing events, meetings, conferences, or conventions.', 'ar' => 'تقدم هذه الدورة المبادئ والممارسات الأساسية للأفراد المعنيين بتخطيط وتنظيم الفعاليات والاجتماعات والمؤتمرات والملتقيات.']],
        'public-relations-and-media-skills' => ['en' => 'Public Relations and Media Skills', 'ar' => 'تنمية مهارات العلاقات العامة والإعلام', 'days' => 5, 'summary' => ['en' => 'Public Relations (PR) professionals must consistently work to present a positive image of their organization while being prepared to respond swiftly to any crisis that may arise.', 'ar' => 'يتعين على المتخصصين في العلاقات العامة (PR) العمل باستمرار على تقديم صورة إيجابية عن مؤسساتهم، مع الاستعداد للاستجابة السريعة لأي أزمة قد تنشأ.']],
        'public-relations-campaigns-from-planning-to-execution' => ['en' => 'Public Relations Campaigns: From Planning to Execution', 'ar' => 'إدارة حملات العلاقات العامة: من التخطيط الى التنفيذ', 'days' => 5, 'summary' => ['en' => 'Effective planning is crucial for any public relations (PR) program.', 'ar' => 'يُعد التخطيط الفعّال أمراً بالغ الأهمية لأي برنامج للعلاقات العامة (PR).']],
        'corporate-social-responsibility-csr' => ['en' => 'Corporate Social Responsibility (CSR)', 'ar' => 'المسؤولية المجتمعية للمؤسسة', 'days' => 3, 'summary' => ['en' => 'Corporate Social Responsibility (CSR) is the principle that encourages businesses to contribute to communities and society without expecting direct financial returns.', 'ar' => 'المسؤولية الاجتماعية للشركات (CSR) هي المبدأ الذي يشجع الشركات على الإسهام في خدمة المجتمعات والمجتمع ككل دون توقع عوائد مالية مباشرة.']],
        'crisis-communication-skills-public-relations' => ['en' => 'Crisis Communication Skills', 'ar' => 'مهارات التواصل في ظل الأزمات', 'days' => 3, 'summary' => ['en' => 'This course equips participants with the tools to understand how a crisis can affect an organization and the strategies necessary to mitigate its impacts.', 'ar' => 'تزوّد هذه الدورة المشاركين بالأدوات اللازمة لفهم كيفية تأثير الأزمات على المؤسسة، والاستراتيجيات الضرورية للحد من آثارها.']],
        'public-relations-and-social-media-campaigns' => ['en' => 'Public Relations & Social Media Campaigns', 'ar' => 'إدارة حملات العلاقات العامة على وسائل التواصل الاجتماعي', 'days' => 3],
        'accounting-for-non-accountants' => ['en' => 'Accounting for Non-Accountants', 'ar' => 'المحاسبة لغير المختصين بها', 'days' => 5, 'summary' => ['en' => 'Accounting is often referred to as the language of business.', 'ar' => 'كثيراً ما يُشار إلى المحاسبة بوصفها لغة الأعمال.']],
        'accounts-payable-accounting-and-management' => ['en' => 'Accounts Payable: Accounting and Management', 'ar' => 'أفضل الممارسات الإدارية لمحاسبة الذمم الدائنة', 'days' => 5, 'summary' => ['en' => 'Accounts Payable (AP) is more than just processing checks and maintaining records—it plays a critical role in the financial health of an organization.', 'ar' => 'لا تقتصر الحسابات الدائنة (AP) على إصدار الشيكات والاحتفاظ بالسجلات فحسب، بل تؤدي دوراً محورياً في السلامة المالية للمؤسسة.']],
        'accounts-receivable-and-credit-policies' => ['en' => 'Accounts Receivable and Credit Policies', 'ar' => 'إدارة سياسات الائتمان والذمم المدينة', 'days' => 5, 'summary' => ['en' => 'A significant portion of a company’s working capital is tied to Accounts Receivable (AR), creating potential liquidity risks.', 'ar' => 'يرتبط جزء كبير من رأس المال العامل للشركة بالذمم المدينة (AR)، مما يخلق مخاطر محتملة على السيولة.']],
        'international-financial-reporting-standards-certifrs' => ['en' => 'International Financial Reporting Standards (CertIFRS)', 'ar' => 'التحضير لشهادة المعايير الدولية لإعداد التقارير المالية (CertIFRS)', 'days' => 5, 'summary' => ['en' => 'The Certificate in International Financial Reporting Standards (CertIFR), awarded by the Association of Certified Chartered Accountants (ACCA) in the UK, is a globally recognized certification.', 'ar' => 'تُعد شهادة المعايير الدولية لإعداد التقارير المالية (CertIFR)، الصادرة عن جمعية المحاسبين القانونيين المعتمدين (ACCA) في المملكة المتحدة، شهادة معترفاً بها عالمياً.']],
        'accounting-for-vat' => ['en' => 'Accounting for VAT', 'ar' => 'القواعد المحاسبية لضريبة القيمة المضافة', 'days' => 3, 'summary' => ['en' => 'With the anticipated implementation of a unified Value Added Tax (VAT) framework across GCC states starting January 1, 2018, this course provides the essential guidance needed to ensure a smooth transition for your organization.', 'ar' => 'مع التطبيق المرتقب لإطار موحّد لضريبة القيمة المضافة (VAT) في دول مجلس التعاون الخليجي اعتباراً من 1 يناير 2018، تقدم هذه الدورة الإرشادات الأساسية اللازمة لضمان انتقال سلس لمؤسستك.']],
        'accounting-and-finance-policies-and-procedures' => ['en' => 'Accounting and Finance Policies and Procedures', 'ar' => 'اعداد السياسات والاجراءات المالية والمحاسبية', 'days' => 5, 'summary' => ['en' => 'Accounting and finance policies and procedures are crucial for implementing effective internal control systems across an organization.', 'ar' => 'تُعدّ السياسات والإجراءات المحاسبية والمالية عنصراً أساسياً في تطبيق أنظمة رقابة داخلية فعّالة على مستوى المؤسسة بأكملها.']],
        'treasury-and-cash-management' => ['en' => 'Treasury and Cash Management', 'ar' => 'إدارة النقد والخزينة', 'days' => 5, 'summary' => ['en' => 'Effective treasury and cash management is critical for organizations to optimize their use of funds while managing exposure to risks, such as fluctuations in interest rates and foreign exchange rates.', 'ar' => 'تُعد الإدارة الفعّالة للخزينة والنقدية أمراً حاسماً للمؤسسات لتحقيق الاستخدام الأمثل لأموالها مع إدارة تعرّضها للمخاطر، مثل تقلبات أسعار الفائدة وأسعار صرف العملات الأجنبية.']],
        'data-analysis-and-reporting-techniques-using-excel' => ['en' => 'Data Analysis and Reporting Techniques Using Excel', 'ar' => 'تحليل البيانات واعداد التقارير باستخدام برنامج اكسل', 'days' => 3, 'summary' => ['en' => 'Excel is an indispensable tool for accountants, finance professionals, and business specialists.', 'ar' => 'يُعد برنامج Excel أداة لا غنى عنها للمحاسبين والمتخصصين في المالية وأخصائيي الأعمال.']],
        'financial-accounting-and-reporting' => ['en' => 'Financial Accounting and Reporting', 'ar' => 'المحاسبة المالية ومهارات اعداد التقارير', 'days' => 5, 'summary' => ['en' => 'In today’s rapidly evolving accounting landscape, staying updated with the latest standards, regulations, and industry practices is essential.', 'ar' => 'في ظل المشهد المحاسبي سريع التطور اليوم، أصبح مواكبة أحدث المعايير واللوائح وممارسات القطاع أمراً ضرورياً.']],
        'inventory-accounting-and-costing' => ['en' => 'Inventory Accounting and Costing', 'ar' => 'مهارات حساب التكلفة وعمليات الجرد', 'days' => 5, 'summary' => ['en' => 'Inventory plays a critical role in the financial health of any business, whether in trading, manufacturing, contracting, or service industries.', 'ar' => 'يؤدي المخزون دوراً حاسماً في السلامة المالية لأي منشأة، سواء في قطاعات التجارة أو التصنيع أو المقاولات أو الخدمات، ويمتد أثره إلى قائمة الدخل والميزانية العمومية.']],
        'basel-iii-risk-assessment-and-stress-testing' => ['en' => 'Basel III, Risk Assessment and Stress Testing', 'ar' => 'تقييم المخاطر واختبار التحمل حسب معايير بازل 3', 'days' => 5, 'summary' => ['en' => 'This intermediate-level course delves into the key provisions of the Basel III regulatory framework, emphasizing risk assessment practices within banks and the critical role of stress testing.', 'ar' => 'تتعمق هذه الدورة متوسطة المستوى في الأحكام الرئيسية للإطار التنظيمي لاتفاقية بازل 3 (Basel III)، مع التركيز على ممارسات تقييم المخاطر داخل البنوك والدور المحوري لاختبارات الضغط.']],
        'effective-budgeting-and-cost-control' => ['en' => 'Effective Budgeting and Cost Control', 'ar' => 'اعداد الموازنات ومراقبة التكالف', 'days' => 5, 'summary' => ['en' => 'Budgeting and cost control are essential skills for professionals across all functions and managerial levels.', 'ar' => 'تُعد الموازنات وضبط التكاليف من المهارات الأساسية للمهنيين في جميع الوظائف والمستويات الإدارية.']],
        'advanced-financial-analysis' => ['en' => 'Advanced Financial Analysis', 'ar' => 'دورة متقدمة في التحليل المالي', 'days' => 5, 'summary' => ['en' => 'This course integrates the core aspects of financial statement analysis to enhance participants\' ability to evaluate business performance, assess financial health, and identify risks facing businesses and investors.', 'ar' => 'تجمع هذه الدورة الجوانب الأساسية لتحليل القوائم المالية بهدف تعزيز قدرة المشاركين على تقييم أداء الأعمال، وتقدير السلامة المالية، وتحديد المخاطر التي تواجه الشركات والمستثمرين.']],
        'financial-management' => ['en' => 'Financial Management', 'ar' => 'أسايات الإدارة المالية', 'days' => 5, 'summary' => ['en' => 'A solid understanding of financial management is essential for making strategic and operational business decisions.', 'ar' => 'يُعدّ الفهم المتين للإدارة المالية أمراً أساسياً لاتخاذ قرارات الأعمال الاستراتيجية والتشغيلية.']],
        'corporate-financial-planning-and-analysis-professional-cert-fp-and-a' => ['en' => 'Corporate Financial Planning & Analysis Professional (Cert FP&A)', 'ar' => 'شهادة محترف التخطيط والتحليل المالي للشركات (Cert FP&A)', 'days' => 5, 'summary' => ['en' => 'In today’s competitive landscape, financial planning and analysis have become vital for organizational success.', 'ar' => 'في ظل المشهد التنافسي الحالي، أصبح التخطيط والتحليل المالي عنصراً حيوياً لنجاح المؤسسات.']],
        'financial-analysis' => ['en' => 'Financial Analysis', 'ar' => 'التحليل المالي', 'days' => 5, 'summary' => ['en' => 'In the modern business environment, finance professionals must go beyond basic reporting to deliver detailed insights into the impact of organizational financial decisions.', 'ar' => 'في بيئة الأعمال الحديثة، يتعيّن على المتخصصين في الشؤون المالية تجاوز إعداد التقارير الأساسية لتقديم رؤى تفصيلية حول أثر القرارات المالية للمؤسسة.']],
        'forecasting-and-analyzing-cash-flow' => ['en' => 'Forecasting and Analyzing Cash Flow', 'ar' => 'إدارة وتحليل التدفق النقدي', 'days' => 5, 'summary' => ['en' => 'Cash flow is the lifeline of any successful and sustainable business.', 'ar' => 'تُعد التدفقات النقدية شريان الحياة لأي عمل تجاري ناجح ومستدام.']],
        'financial-acumen' => ['en' => 'Financial Acumen', 'ar' => 'أساسيات تحقيق الفطنة المالية', 'days' => 5, 'summary' => ['en' => 'In today’s fast-paced business world, professionals are constantly faced with decisions that demand sound judgment and strategic thinking.', 'ar' => 'في عالم الأعمال المتسارع اليوم، يواجه المهنيون باستمرار قرارات تتطلب حكماً سليماً وتفكيراً استراتيجياً.']],
        'financial-forecasting-tools-and-techniques' => ['en' => 'Financial Forecasting: Tools and Techniques', 'ar' => 'تقنيات وأدوات التنبؤات المالية', 'days' => 5, 'summary' => ['en' => 'Forecasting future events is one of the most challenging aspects of decision-making for professionals.', 'ar' => 'يُعدّ التنبؤ بالأحداث المستقبلية من أكثر جوانب اتخاذ القرار تحدياً بالنسبة للمهنيين.']],
        'preparing-financial-statements-and-the-annual-report' => ['en' => 'Preparing Financial Statements and the Annual Report', 'ar' => 'إعداد القوائم المالية والتقارير المالية السنوية', 'days' => 5, 'summary' => ['en' => 'Financial statements and the annual report are essential tools for communicating a company’s financial health and performance to stakeholders.', 'ar' => 'تُعد القوائم المالية والتقرير السنوي أدوات أساسية لإبلاغ أصحاب المصلحة بالوضع المالي للشركة وأدائها.']],
        'internal-control-compliance-operational-and-financial' => ['en' => 'Internal Control: Compliance, Operational and Financial', 'ar' => 'ضوابط الامتثال الداخلية للعمليات التشغيلية والمالية', 'days' => 5, 'summary' => ['en' => 'Internal controls play a vital role in ensuring organizational efficiency and mitigating risk.', 'ar' => 'تؤدي الرقابة الداخلية دوراً حيوياً في ضمان كفاءة المؤسسة والحد من المخاطر.']],
        'payroll-preparation-analysis-and-management-finance' => ['en' => 'Payroll: Preparation, Analysis and Management', 'ar' => 'إدارة إعداد وتحليل الرواتب والمستحقات', 'days' => 5, 'summary' => ['en' => 'Employee compensation, including payroll and benefits, represents one of the largest expenses for any company, second only to the Cost of Goods Sold (COGS), rent, and depreciation.', 'ar' => 'تُمثّل تعويضات الموظفين، بما في ذلك الرواتب والمزايا، أحد أكبر بنود المصروفات في أي شركة، ولا يسبقها في ذلك سوى تكلفة البضاعة المباعة (COGS) والإيجار والإهلاك.']],
        'trade-finance-letters-of-credit-and-bank-guarantees' => ['en' => 'Trade Finance, Letters of Credit and Bank Guarantees', 'ar' => 'أساسيات التمويل التجاري والاعتمادات المستندية والكفالات البنكية', 'days' => 5, 'summary' => ['en' => 'Protecting company assets during transactions with both local and international customers is crucial for business success and sustainability.', 'ar' => 'تُعد حماية أصول الشركة خلال المعاملات مع العملاء المحليين والدوليين أمراً بالغ الأهمية لنجاح الأعمال واستدامتها.']],
        'managing-the-collections-and-credit-control-team' => ['en' => 'Managing the Collections and Credit Control Team', 'ar' => 'إدارة فرق التحصيل والحالات الإئتمانية', 'days' => 5, 'summary' => ['en' => 'The structure, management, and positioning of a collections and credit control department significantly influence its impact on an organization, potentially transforming it into a key driver of profitability.', 'ar' => 'يؤثر هيكل إدارة التحصيل ومراقبة الائتمان وأسلوب إدارتها وموقعها تأثيراً كبيراً في دورها داخل المؤسسة، وقد يحوّلها إلى محرك رئيسي للربحية.']],
        'fixed-assets-accounting-and-management' => ['en' => 'Fixed Assets Accounting and Management', 'ar' => 'إدارة محاسبة الأصول الثابتة', 'days' => 5, 'summary' => ['en' => 'Effective fixed assets management and accounting are crucial for organizations, as these assets are key resources for product production and long-term benefits generation.', 'ar' => 'تُعد الإدارة والمحاسبة الفعّالتان للأصول الثابتة أمراً بالغ الأهمية للمؤسسات، إذ تمثّل هذه الأصول موارد رئيسية لإنتاج المنتجات وتحقيق المنافع على المدى الطويل.']],
        'forensic-accounting-and-fraud-control' => ['en' => 'Forensic Accounting and Fraud Control', 'ar' => 'أساسيات المحاسبة العدلية ومكافحة الاحتيال', 'days' => 5, 'summary' => ['en' => 'Forensic accounting and fraud auditing are critical fields gaining prominence as fraud and accounting scandals become more widespread.', 'ar' => 'تُعد المحاسبة الجنائية وتدقيق الاحتيال من المجالات الحيوية التي تزداد أهميتها مع اتساع انتشار حالات الاحتيال والفضائح المحاسبية.']],
        'corporate-governance-principles-policies-and-best-practices' => ['en' => 'Corporate Governance: Principles, Policies and Best Practices', 'ar' => 'أسس وسياسات وأفضل ممارسات حوكمة المؤسسات', 'days' => 5, 'summary' => ['en' => 'Corporate governance has become an increasingly prominent topic in both academic and legislative circles, reflecting its critical role in modern business.', 'ar' => 'أصبحت حوكمة الشركات موضوعاً يحظى باهتمام متزايد في الأوساط الأكاديمية والتشريعية على حد سواء، مما يعكس دورها المحوري في بيئة الأعمال الحديثة.']],
        'data-governance-protection-and-compliance-management' => ['en' => 'Data Governance, Protection and Compliance Management', 'ar' => 'حوكمة البيانات وإدارة الامتثال', 'days' => 5, 'summary' => ['en' => 'Data Governance and Compliance provide a framework of decision rights and accountability to guide the management of information throughout its lifecycle.', 'ar' => 'توفر حوكمة البيانات والامتثال إطاراً لحقوق اتخاذ القرار والمساءلة لتوجيه إدارة المعلومات طوال دورة حياتها.']],
        'governance-risk-and-compliance-grc' => ['en' => 'Governance, Risk and Compliance (GRC)', 'ar' => 'الحوكمة وإدارة المخاطر والامتثال', 'days' => 5, 'summary' => ['en' => 'Governance, Risk, and Compliance (GRC) are interconnected disciplines that play a crucial role in modern corporate management.', 'ar' => 'تُعدّ الحوكمة والمخاطر والامتثال (GRC) تخصصات مترابطة تؤدي دوراً محورياً في إدارة الشركات الحديثة.']],
        'fraud-detection-and-prevention-for-the-insurance-industry' => ['en' => 'Fraud Detection and Prevention for the Insurance Industry', 'ar' => 'كشف الاحتيال والوقاية منه في مجال التأمين', 'days' => 3, 'summary' => ['en' => 'This course is designed to equip professionals in the insurance industry with the skills and tools to prevent, detect, investigate, and prosecute fraud.', 'ar' => 'صُممت هذه الدورة لتزويد المهنيين العاملين في قطاع التأمين بالمهارات والأدوات اللازمة لمنع الاحتيال وكشفه والتحقيق فيه وملاحقة مرتكبيه قضائياً.']],
        'foreign-exchange-money-markets-and-derivatives' => ['en' => 'Foreign Exchange, Money Markets and Derivatives', 'ar' => 'النقد الأجنبي وأسواق المال', 'days' => 5, 'summary' => ['en' => 'The global foreign exchange (FX) and money markets represent the largest and most dynamic financial markets worldwide, with daily FX transactions exceeding $5 trillion.', 'ar' => 'تمثل أسواق الصرف الأجنبي (FX) وأسواق المال العالمية أكبر الأسواق المالية في العالم وأكثرها ديناميكية، إذ تتجاوز معاملات الصرف الأجنبي اليومية 5 تريليونات دولار.']],
        'anti-money-laundering' => ['en' => 'Anti Money Laundering', 'ar' => 'مكافحة عمليات غسيل الأموال', 'days' => 3, 'summary' => ['en' => 'This course delivers a detailed and practical examination of money laundering schemes, anti-money laundering (AML) legislation, and effective countermeasures.', 'ar' => 'تقدّم هذه الدورة دراسة تفصيلية وعملية لأساليب غسل الأموال، وتشريعات مكافحة غسل الأموال (AML)، والتدابير المضادة الفعّالة.']],
        'enterprise-risk-management' => ['en' => 'Enterprise Risk Management', 'ar' => 'إدارة مخاطر المؤسسات', 'days' => 3, 'summary' => ['en' => 'Enterprise Risk Management (ERM) has advanced significantly since its inception in the 1970s.', 'ar' => 'شهدت إدارة المخاطر المؤسسية (ERM) تطوراً كبيراً منذ نشأتها في سبعينيات القرن الماضي.']],
        'report-writing-for-the-internal-auditor' => ['en' => 'Report Writing for the Internal Auditor', 'ar' => 'مهارات كتابة التقارير للمدقق الداخلي', 'days' => 3, 'summary' => ['en' => 'In today’s professional landscape, the quality of an audit department is often judged by its key deliverable: the audit report.', 'ar' => 'في البيئة المهنية الحالية، كثيراً ما تُقاس جودة إدارة التدقيق بمخرجها الرئيسي: تقرير التدقيق.']],
        'essentials-of-internal-audit' => ['en' => 'Essentials of Internal Audit', 'ar' => 'أساسيات التدقيق الداخلي', 'days' => 5, 'summary' => ['en' => 'Internal auditing, as defined by the Institute of Internal Auditors, is an independent and objective assurance and consulting activity aimed at adding value and improving an organization’s operations.', 'ar' => 'يُعرّف معهد المدققين الداخليين التدقيق الداخلي بأنه نشاط تأكيدي واستشاري مستقل وموضوعي يهدف إلى إضافة قيمة للمؤسسة وتحسين عملياتها.']],
        'certified-internal-auditor-exam-preparation' => ['en' => 'Certified Internal Auditor Exam Preparation', 'ar' => 'التحضير لشهادة المدقق الداخلي المعتمد', 'days' => 5, 'summary' => ['en' => 'The IIA’s CIA Learning System Program is designed to expand your internal audit knowledge, build confidence for addressing today’s internal audit challenges, and prepare you for the Certified Internal Auditor (CIA) exam.', 'ar' => 'صُمّم برنامج نظام التعلّم لشهادة المدقق الداخلي المعتمد (CIA Learning System) الصادر عن معهد المدققين الداخليين (IIA) لتوسيع معارفك في مجال التدقيق الداخلي، وتعزيز ثقتك في التعامل مع تحديات التدقيق الداخلي الراهنة، وإعدادك لاجتياز امتحان المدقق الداخلي المعتمد (CIA).']],
        'certified-information-systems-auditor-cisa' => ['en' => 'Certified Information Systems Auditor (CISA)', 'ar' => 'مدقق نظم المعلومات المعتمد (CISA)', 'days' => 5, 'summary' => ['en' => 'This course is designed to help candidates prepare for sitting the ISACA CISA certification examination.', 'ar' => 'صُممت هذه الدورة لمساعدة المرشحين على الاستعداد لأداء اختبار شهادة مدقق نظم المعلومات المعتمد (CISA) الصادرة عن ISACA.']],
        'risk-based-internal-audit' => ['en' => 'Risk-Based Internal Audit', 'ar' => 'التدقيق الداخلي في ظل المخاطر', 'days' => 5, 'summary' => ['en' => 'Internal auditing is defined by the Institute of Internal Auditors as an independent, objective assurance and consulting activity designed to add value and improve an organization’s operations.', 'ar' => 'يعرّف معهد المدققين الداخليين التدقيق الداخلي بأنه نشاط تأكيدي واستشاري مستقل وموضوعي، مصمم لإضافة قيمة إلى عمليات المؤسسة وتحسينها.']],
        'it-auditing-and-it-fraud-detection' => ['en' => 'IT Auditing and IT Fraud Detection', 'ar' => 'التدقيق وكشف الاحتيال باستخدام تكنولوجيا المعلومات', 'days' => 3, 'summary' => ['en' => 'In today’s digital age, preventing and investigating IT fraud has become a critical aspect of corporate operations.', 'ar' => 'في العصر الرقمي الحالي، أصبح منع الاحتيال في تقنية المعلومات والتحقيق فيه جانباً بالغ الأهمية في عمليات الشركات.']],
        'drafting-contracts-and-writing-scope-of-work' => ['en' => 'Drafting Contracts and Writing Scope of Work', 'ar' => 'مهارات إعداد العقود وكتابة نطاق العمل', 'days' => 5, 'summary' => ['en' => 'This course equips participants with the knowledge and skills needed to draft precise project scopes of work and create simple contracts.', 'ar' => 'تزوّد هذه الدورة المشاركين بالمعارف والمهارات اللازمة لصياغة نطاقات عمل دقيقة للمشاريع وإعداد عقود بسيطة.']],
        'essential-skills-for-contract-professionals' => ['en' => 'Essential Skills for Contract Professionals', 'ar' => 'المهارات الأساسية لأخصائيي العقود', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential skills required to effectively manage contracts, including communication, negotiation, and conflict management.', 'ar' => 'صُمّمت هذه الدورة لتزويد المشاركين بالمهارات الأساسية اللازمة لإدارة العقود بفاعلية، بما في ذلك مهارات التواصل والتفاوض وإدارة النزاعات.']],
        'arbitration-and-dispute-resolution' => ['en' => 'Arbitration and Dispute Resolution', 'ar' => 'التحكيم وفض المنازعات', 'days' => 3, 'summary' => ['en' => 'Effective dispute resolution minimizes costs and preserves relationships often strained by commercial disputes.', 'ar' => 'تسهم التسوية الفعّالة للنزاعات في خفض التكاليف والحفاظ على العلاقات التي كثيراً ما تتأثر سلباً بالنزاعات التجارية.']],
        'managing-change-orders-and-contractual-claims' => ['en' => 'Managing Change Orders and Contractual Claims', 'ar' => 'إدارة التغييرات و المطالبات العقدية', 'days' => 5, 'summary' => ['en' => 'This course is designed to provide participants with foundational knowledge and essential skills to effectively address claims, variations, and disputes between principals and contractors.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف الأساسية والمهارات الضرورية للتعامل بفاعلية مع المطالبات والتغييرات والنزاعات بين أصحاب العمل والمقاولين.']],
        'effective-contract-preparation' => ['en' => 'Effective Contract Preparation', 'ar' => 'المهارات الفعالة في اعداد العقود', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential knowledge, concepts, and skills required to manage all tasks in the pre-award phase of a contract.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف والمفاهيم والمهارات الأساسية اللازمة لإدارة جميع المهام في مرحلة ما قبل ترسية العقد.']],
        'tendering-contract-preparation-and-bid-evaluation' => ['en' => 'Tendering, Contract Preparation & Bid Evaluation', 'ar' => 'تحضير عقود المناقصات وفض العروض', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the essential knowledge, concepts, and skills required to manage tendering processes and bid evaluations effectively.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف والمفاهيم والمهارات الأساسية اللازمة لإدارة عمليات المناقصات وتقييم العطاءات بفاعلية.']],
        'negotiating-contracts-successfully' => ['en' => 'Negotiating Contracts Successfully', 'ar' => 'مهارات التفاوض الناجح لأخصائيي العقود', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the skills, knowledge, and strategies required to effectively negotiate throughout the contract life cycle.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات والمعارف والاستراتيجيات اللازمة للتفاوض بفاعلية طوال دورة حياة العقد.']],
        'fidic-contracts-management' => ['en' => 'FIDIC Contracts Management', 'ar' => 'إدارة عقود الفيديك FIDIC', 'days' => 3, 'summary' => ['en' => 'This course offers practical insights for professionals involved in the management or administration of projects governed by FIDIC forms of contracts.', 'ar' => 'تقدّم هذه الدورة رؤى عملية للمهنيين المعنيين بإدارة المشاريع التي تحكمها نماذج عقود FIDIC أو بإدارة عقودها.']],
        'contract-management-for-non-contract-professionals' => ['en' => 'Contract Management for Non-Contract Professionals', 'ar' => 'مهارات إدارة العقود لغير المختصين بها', 'days' => 3, 'summary' => ['en' => 'The primary objective of this course is to equip participants with the knowledge, skills, and tools needed to manage and administer contracts effectively after they are awarded.', 'ar' => 'يتمثل الهدف الرئيسي من هذه الدورة في تزويد المشاركين بالمعارف والمهارات والأدوات اللازمة لإدارة العقود وإدارتها التنفيذية بفاعلية بعد ترسيتها.']],
        'contract-administration-understanding-and-implementing-contractual-obligations' => ['en' => 'Contract Administration: Understanding and Implementing Contractual Obligations', 'ar' => 'فهم وتطبيق الالتزامات التعاقدية في إدارة العقود', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip participants with the knowledge, skills, and tools necessary to effectively manage and administer contracts post-award.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمعارف والمهارات والأدوات اللازمة لإدارة العقود وتنفيذها بفاعلية بعد الترسية.']],
        'mergers-and-acquisitions' => ['en' => 'Mergers and Acquisitions', 'ar' => 'عمليات الدمج والاستحواذ', 'days' => 3, 'summary' => ['en' => 'This hands-on course provides a comprehensive understanding of the Mergers and Acquisitions (M&A) process, from valuing shares to finalizing the deal.', 'ar' => 'تقدّم هذه الدورة التطبيقية فهماً شاملاً لعملية الاندماج والاستحواذ (M&A)، بدءاً من تقييم الأسهم وصولاً إلى إتمام الصفقة.']],
        'strategic-quality-management' => ['en' => 'Strategic Quality Management', 'ar' => 'الإدارة الاستراتيجية للجودة', 'days' => 5, 'summary' => ['en' => 'This course offers a comprehensive blend of strategy and quality, equipping participants with the skills needed to design and implement strategic quality plans for their organizations.', 'ar' => 'تقدّم هذه الدورة مزيجاً شاملاً بين الاستراتيجية والجودة، إذ تزوّد المشاركين بالمهارات اللازمة لتصميم خطط الجودة الاستراتيجية وتنفيذها في مؤسساتهم.']],
        'efqm-internal-assessor' => ['en' => 'EFQM: Internal Assessor', 'ar' => 'المقيم الداخلي EFQM', 'days' => 3, 'summary' => ['en' => 'This course is designed to equip participants with the skills and knowledge needed to conduct internal assessments using the EFQM Excellence Model and the RADAR assessment methodology.', 'ar' => 'صُممت هذه الدورة لتزويد المشاركين بالمهارات والمعارف اللازمة لإجراء التقييمات الداخلية باستخدام نموذج EFQM للتميز ومنهجية التقييم RADAR.']],
        'efqm-journey-to-excellence-j2e' => ['en' => 'EFQM: Journey to Excellence (J2E)', 'ar' => 'رحلة الى التميز EFQM', 'days' => 3, 'summary' => ['en' => 'What does excellence truly mean?', 'ar' => 'ما المعنى الحقيقي للتميّز؟']],
        'efqm-leaders-for-excellence-l4e' => ['en' => 'EFQM: Leaders for Excellence (L4E)', 'ar' => 'قادة التميز EFQM', 'days' => 3, 'summary' => ['en' => 'What does excellence mean?', 'ar' => 'ماذا يعني التميز؟']],
        'lean-thinking-a-strategy-for-operational-excellence' => ['en' => 'Lean Thinking: A Strategy for Operational Excellence', 'ar' => 'التفكير الرشيق: استراتيجية التميّز في العمليات المؤسسية', 'days' => 5, 'summary' => ['en' => 'Lean Thinking is a transformative approach aimed at achieving operational excellence within organizations.', 'ar' => 'يُعد التفكير الرشيق (Lean Thinking) نهجاً تحويلياً يهدف إلى تحقيق التميّز التشغيلي داخل المؤسسات.']],
        'total-quality-management-tqm' => ['en' => 'Total Quality Management (TQM)', 'ar' => 'إدارة الجودة الشاملة', 'days' => 5, 'summary' => ['en' => 'This course provides participants with an in-depth understanding of the history and evolution of quality concepts, including the contributions of renowned quality gurus and tools.', 'ar' => 'تزوّد هذه الدورة المشاركين بفهم معمّق لتاريخ مفاهيم الجودة وتطوّرها، بما في ذلك إسهامات روّاد الجودة المشهورين وأدواتهم.']],
        'certified-lean-six-sigma-green-belt' => ['en' => 'Certified Lean Six Sigma Green Belt', 'ar' => 'دورة الحزام الأخضر المعتمدة في سداسية سيجما', 'days' => 5, 'summary' => ['en' => 'Become a certified Six Sigma practitioner and join the ranks of thousands of successful professionals we’ve trained over the past two decades.', 'ar' => 'احصل على شهادة ممارس معتمد في Six Sigma وانضم إلى آلاف المهنيين الناجحين الذين درّبناهم على مدى العقدين الماضيين.']],
        'certified-six-sigma-yellow-belt' => ['en' => 'Certified Six Sigma Yellow Belt', 'ar' => 'دورة الحزام الأصفر المعتمدة في سداسية سيجما', 'days' => 5, 'summary' => ['en' => 'This engaging course introduces participants to the renowned Motorola Six Sigma methodology, providing them with the foundational knowledge to identify and address organizational challenges effectively.', 'ar' => 'تقدّم هذه الدورة التفاعلية للمشاركين منهجية Six Sigma الشهيرة التي طورتها شركة Motorola، وتزوّدهم بالمعارف الأساسية لتحديد التحديات المؤسسية ومعالجتها بفاعلية.']],
        'iso-14001-2015-transition-training-environmental-management-system' => ['en' => 'ISO 14001:2015 Transition Training: Environmental Management System', 'ar' => 'التدريب الانتقالي على ISO 14001:2015: نظام الإدارة البيئية', 'days' => 3, 'summary' => ['en' => 'This training program is tailored for managers overseeing environmental and sustainability responsibilities.', 'ar' => 'صُمم هذا البرنامج التدريبي خصيصاً للمديرين المشرفين على المسؤوليات البيئية ومسؤوليات الاستدامة.']],
        'iso-9001-2015-transition-training-quality-management-system' => ['en' => 'ISO 9001: 2015 Transition Training: Quality Management System', 'ar' => 'التدريب الانتقالي على ISO 9001:2015: نظام إدارة الجودة', 'days' => 3, 'summary' => ['en' => 'The ISO 9001:2015 Quality Management System standard is globally recognized and adaptable to both manufacturing and service industries.', 'ar' => 'يحظى معيار نظام إدارة الجودة ISO 9001:2015 باعتراف عالمي، ويمكن تكييفه ليلائم قطاعي التصنيع والخدمات على حد سواء.']],
        'quality-organizational-excellence' => ['en' => 'Quality/Organizational Excellence', 'ar' => 'التميز في جودة الأداء المؤسسي', 'days' => 5, 'summary' => ['en' => 'Become a quality leader within your organization.', 'ar' => 'كن قائداً للجودة داخل مؤسستك.']],
        'improving-productivity-through-quality-enhancement-and-cost-reduction' => ['en' => 'Improving Productivity through Quality Enhancement and Cost Reduction', 'ar' => 'تحسين الانتاجية عبر تحسين الجودة وخفض التكاليف', 'days' => 5, 'summary' => ['en' => 'How can organizations improve productivity?', 'ar' => 'كيف يمكن للمؤسسات تحسين الإنتاجية؟']],
