        'machine-learning-specialization' => ['en' => 'Machine Learning Specialization', 'ar' => 'التخصص في تعلّم الآلة (Machine Learning)', 'days' => 5, 'summary' => ['en' => 'The Machine Learning Specialization provides a comprehensive and in-depth understanding of machine learning techniques and algorithms.', 'ar' => 'يقدم برنامج التخصص في تعلّم الآلة فهماً شاملاً ومعمّقاً لتقنيات تعلّم الآلة وخوارزمياته.']],
        'iot-specialization' => ['en' => 'IoT Specialization', 'ar' => 'التخصص في إنترنت الأشياء (IoT)', 'days' => 5, 'summary' => ['en' => 'The Internet of Things (IoT) Specialization provides a comprehensive introduction to IoT technologies and applications.', 'ar' => 'يقدّم برنامج التخصص في إنترنت الأشياء (IoT) مقدمة شاملة إلى تقنيات إنترنت الأشياء وتطبيقاتها.']],
        'microsoft-certified-azure-ai-engineer-associate' => ['en' => 'Microsoft Certified: Azure AI Engineer Associate', 'ar' => 'شهادة Microsoft Certified: Azure AI Engineer Associate', 'days' => 5, 'summary' => ['en' => 'The Microsoft Certified: Azure AI Engineer Associate course is designed to equip participants with the skills needed to design and implement AI solutions on Microsoft Azure.', 'ar' => 'صُمّمت دورة Microsoft Certified: Azure AI Engineer Associate لتزويد المشاركين بالمهارات اللازمة لتصميم حلول الذكاء الاصطناعي وتطبيقها على منصة Microsoft Azure.']],
        'generative-ai' => ['en' => 'Generative AI', 'ar' => 'الذكاء الاصطناعي التوليدي (Generative AI)', 'days' => 5, 'summary' => ['en' => 'This course provides a comprehensive introduction to Generative Artificial Intelligence (AI), covering the principles, applications, and ethical considerations of generative models such as GPT, GANs, VAEs, and diffusion models.', 'ar' => 'تقدّم هذه الدورة مدخلاً شاملاً إلى الذكاء الاصطناعي التوليدي (Generative AI)، وتغطي مبادئ النماذج التوليدية مثل GPT وشبكات GANs وVAEs ونماذج الانتشار (Diffusion Models)، وتطبيقاتها، والاعتبارات الأخلاقية المرتبطة بها.']],
        'generative-ai-for-ceo' => ['en' => 'Generative AI for CEO', 'ar' => 'الذكاء الاصطناعي التوليدي للرؤساء التنفيذيين', 'days' => 5, 'summary' => ['en' => 'This course is designed for CEOs and senior executives seeking to understand and leverage Generative AI for strategic decision-making, operational efficiency, and innovation.', 'ar' => 'صُمّمت هذه الدورة للرؤساء التنفيذيين وكبار التنفيذيين الساعين إلى فهم الذكاء الاصطناعي التوليدي (Generative AI) وتوظيفه في اتخاذ القرارات الاستراتيجية ورفع الكفاءة التشغيلية وتعزيز الابتكار.']],
        'generative-ai-and-prompt-engineering-using-python' => ['en' => 'Generative AI and Prompt Engineering using Python', 'ar' => 'الذكاء الاصطناعي التوليدي وهندسة الأوامر (Prompt Engineering) باستخدام Python', 'days' => 5, 'summary' => ['en' => 'This course provides an in-depth understanding of Generative AI and Prompt Engineering, focusing on Large Language Models (LLMs) like GPT (Chat-GPT), Claude, LLa-MA, and Gemini and image-generation models like Stable Diffusion and DALL·E.', 'ar' => 'تقدّم هذه الدورة فهماً معمّقاً للذكاء الاصطناعي التوليدي وهندسة الأوامر (Prompt Engineering)، مع التركيز على النماذج اللغوية الكبيرة (LLMs) مثل GPT ‏(Chat-GPT) وClaude وLLa-MA وGemini، ونماذج توليد الصور مثل Stable Diffusion وDALL·E.']],
        'generative-ai-for-cybersecurity-domain' => ['en' => 'Generative AI for Cybersecurity Domain', 'ar' => 'الذكاء الاصطناعي التوليدي في مجال الأمن السيبراني', 'days' => 5, 'summary' => ['en' => 'This course provides a comprehensive understanding of Generative AI’s applications in Cybersecurity.', 'ar' => 'تقدّم هذه الدورة فهماً شاملاً لتطبيقات الذكاء الاصطناعي التوليدي في مجال الأمن السيبراني.']],
        'generative-ai-for-devops-engineers' => ['en' => 'Generative AI for DevOps Engineers', 'ar' => 'الذكاء الاصطناعي التوليدي لمهندسي DevOps', 'days' => 5, 'summary' => ['en' => 'This course provides an in-depth exploration of how Generative AI can enhance DevOps workflows, including CI/CD automation, infrastructure as code (IaC), log analysis, anomaly detection, security monitoring, and incident response.', 'ar' => 'تقدم هذه الدورة استكشافاً معمّقاً لكيفية إسهام الذكاء الاصطناعي التوليدي (Generative AI) في تعزيز مسارات عمل DevOps، بما في ذلك أتمتة CI/CD، والبنية التحتية ككود (IaC)، وتحليل السجلات، واكتشاف الحالات الشاذة، والمراقبة الأمنية، والاستجابة للحوادث.']],
        'generative-ai-for-django-web-application-developers' => ['en' => 'Generative AI for Django Web Application Developers', 'ar' => 'الذكاء الاصطناعي التوليدي لمطوّري تطبيقات الويب باستخدام Django', 'days' => 5, 'summary' => ['en' => 'This course explores how Generative AI can be integrated into Django-based web applications, enhancing functionality with AI-driven content generation, chatbots, recommendations, search optimization, code automation, and intelligent analytics.', 'ar' => 'تستكشف هذه الدورة كيفية دمج الذكاء الاصطناعي التوليدي (Generative AI) في تطبيقات الويب المبنية على Django، بما يعزّز وظائفها من خلال توليد المحتوى بالذكاء الاصطناعي، وروبوتات المحادثة، والتوصيات، وتحسين البحث، وأتمتة الشيفرة البرمجية، والتحليلات الذكية.']],
        'generative-ai-course-for-everyone' => ['en' => 'Generative AI Course for Everyone', 'ar' => 'دورة الذكاء الاصطناعي التوليدي للجميع', 'days' => 5, 'summary' => ['en' => 'This course provides a beginner-friendly introduction to Generative AI, covering its fundamentals, real-world applications, ethical considerations, and hands-on usage of AI tools.', 'ar' => 'تقدّم هذه الدورة مدخلاً مبسّطاً مناسباً للمبتدئين إلى الذكاء الاصطناعي التوليدي (Generative AI)، وتغطي أساسياته، وتطبيقاته الواقعية، والاعتبارات الأخلاقية المرتبطة به، والاستخدام العملي لأدوات الذكاء الاصطناعي.']],
        'generative-ai-for-full-stack-developers' => ['en' => 'Generative AI for Full Stack Developers', 'ar' => 'الذكاء الاصطناعي التوليدي لمطوري Full Stack', 'days' => 5, 'summary' => ['en' => 'This course is designed to equip Full Stack Developers with the knowledge and skills to integrate Generative AI into modern web applications.', 'ar' => 'صُممت هذه الدورة لتزويد مطوري Full Stack بالمعارف والمهارات اللازمة لدمج الذكاء الاصطناعي التوليدي في تطبيقات الويب الحديثة.']],
        'generative-ai-for-full-stack-developers-django-react-js-postgresql' => ['en' => 'Generative AI for Full Stack Developers (Django + React.js + PostgreSQL)', 'ar' => 'الذكاء الاصطناعي التوليدي للمطوّرين المتكاملين (Django + React.js + PostgreSQL)', 'days' => 5, 'summary' => ['en' => 'This course is designed to help Full Stack Developers integrate Generative AI into web applications built with Django (Backend), React.js (Frontend), and PostgreSQL (Database).', 'ar' => 'صُممت هذه الدورة لمساعدة المطوّرين المتكاملين (Full Stack Developers) على دمج الذكاء الاصطناعي التوليدي في تطبيقات الويب المبنية باستخدام Django (الواجهة الخلفية) وReact.js (الواجهة الأمامية) وPostgreSQL (قاعدة البيانات).']],
        'generative-ai-for-it-leaders' => ['en' => 'Generative AI for IT Leaders', 'ar' => 'الذكاء الاصطناعي التوليدي لقادة تقنية المعلومات', 'days' => 5, 'summary' => ['en' => 'This training course is designed to equip IT leaders with a deep understanding of generative AI technologies, their applications, and strategic implementation within organizations.', 'ar' => 'صُممت هذه الدورة التدريبية لتزويد قادة تقنية المعلومات بفهم معمّق لتقنيات الذكاء الاصطناعي التوليدي وتطبيقاتها وتطبيقها الاستراتيجي داخل المؤسسات.']],
        'generative-ai-for-it-project-managers' => ['en' => 'Generative AI for IT Project Managers', 'ar' => 'الذكاء الاصطناعي التوليدي لمديري مشاريع تقنية المعلومات', 'days' => 5, 'summary' => ['en' => 'This course is designed for IT Project Managers who want to integrate Generative AI into project management workflows to improve efficiency, decision-making, and automation.', 'ar' => 'صُممت هذه الدورة لمديري مشاريع تقنية المعلومات الراغبين في دمج الذكاء الاصطناعي التوليدي في سير عمل إدارة المشاريع لتحسين الكفاءة واتخاذ القرارات والأتمتة.']],
        'generative-ai-for-it-security-domain' => ['en' => 'Generative AI for IT Security Domain', 'ar' => 'الذكاء الاصطناعي التوليدي في مجال أمن تقنية المعلومات', 'days' => 5, 'summary' => ['en' => 'This training course is designed for IT security professionals to understand the risks, opportunities, and applications of generative AI in cybersecurity.', 'ar' => 'صُمّمت هذه الدورة التدريبية لتمكين المتخصصين في أمن تقنية المعلومات من فهم مخاطر الذكاء الاصطناعي التوليدي (Generative AI) وفرصه وتطبيقاته في مجال الأمن السيبراني.']],
        'generative-ai-for-python-automation-testing' => ['en' => 'Generative AI for Python Automation Testing', 'ar' => 'الذكاء الاصطناعي التوليدي لأتمتة الاختبارات باستخدام Python', 'days' => 5, 'summary' => ['en' => 'This course is designed for QA engineers, test automation developers, and software testers who want to leverage Generative AI for enhanced test case generation, automation scripting, debugging, and test optimization.', 'ar' => 'صُمّمت هذه الدورة لمهندسي ضمان الجودة (QA) ومطوّري أتمتة الاختبارات ومختبري البرمجيات الراغبين في توظيف الذكاء الاصطناعي التوليدي لتحسين توليد حالات الاختبار، وكتابة نصوص الأتمتة البرمجية، وتصحيح الأخطاء، وتحسين الاختبارات.']],
        'generative-ai-for-software-developers' => ['en' => 'Generative AI for Software Developers', 'ar' => 'الذكاء الاصطناعي التوليدي لمطوري البرمجيات', 'days' => 5, 'summary' => ['en' => 'This course is designed for software developers, engineers, and architects who want to leverage Generative AI for code generation, debugging, optimization, and automation.', 'ar' => 'صُممت هذه الدورة لمطوري البرمجيات ومهندسيها ومهندسي البنى البرمجية الراغبين في الاستفادة من الذكاء الاصطناعي التوليدي (Generative AI) في توليد الكود وتصحيح الأخطاء والتحسين والأتمتة.']],
        'generative-ai-for-managers-and-ceos' => ['en' => 'Generative AI for Managers & CEOs', 'ar' => 'الذكاء الاصطناعي التوليدي للمديرين والرؤساء التنفيذيين', 'days' => 5, 'summary' => ['en' => 'This course is designed for business leaders, executives, and managers who want to understand how Generative AI can transform their businesses, improve decision-making, enhance operational efficiency, and drive innovation.', 'ar' => 'صُمّمت هذه الدورة لقادة الأعمال والتنفيذيين والمديرين الراغبين في فهم كيف يمكن للذكاء الاصطناعي التوليدي (Generative AI) أن يُحدث تحولاً في أعمالهم، ويحسّن اتخاذ القرارات، ويعزّز الكفاءة التشغيلية، ويدفع عجلة الابتكار.']],
        'generative-ai-for-managers-and-ceos-in-manufacturing' => ['en' => 'Generative AI for Managers & CEOs in Manufacturing', 'ar' => 'الذكاء الاصطناعي التوليدي للمديرين والرؤساء التنفيذيين في قطاع التصنيع', 'days' => 5, 'summary' => ['en' => 'This course is designed for managers, executives, and business leaders in the manufacturing industry who wish to explore and adopt Generative AI to optimize their operations, improve product design, enhance production efficiency, and drive innovation.', 'ar' => 'صُمّمت هذه الدورة للمديرين والتنفيذيين وقادة الأعمال في قطاع التصنيع الراغبين في استكشاف الذكاء الاصطناعي التوليدي وتبنّيه لتحسين عملياتهم، وتطوير تصميم المنتجات، ورفع كفاءة الإنتاج، ودفع عجلة الابتكار.']],
        'generative-ai-using-python' => ['en' => 'Generative AI using Python', 'ar' => 'الذكاء الاصطناعي التوليدي باستخدام Python', 'days' => 5, 'summary' => ['en' => 'This course provides an in-depth exploration of Generative AI techniques using Python, empowering participants to design and implement AI models that can generate data, create content, and solve complex problems.', 'ar' => 'تقدّم هذه الدورة استكشافاً معمّقاً لأساليب الذكاء الاصطناعي التوليدي باستخدام Python، بما يمكّن المشاركين من تصميم نماذج ذكاء اصطناعي قادرة على توليد البيانات وإنشاء المحتوى وحل المشكلات المعقدة وتطبيقها.']],
        'certified-in-the-governance-of-enterprise-it-cgeit-isaca' => ['en' => 'Certified in the Governance of Enterprise IT (CGEIT) – ISACA', 'ar' => 'شهادة معتمد في حوكمة تقنية المعلومات المؤسسية (CGEIT) – ISACA', 'days' => 5, 'summary' => ['en' => 'The CGEIT certification course provides a deep understanding of the principles and practices of IT governance.', 'ar' => 'تقدّم دورة شهادة CGEIT فهماً معمّقاً لمبادئ حوكمة تقنية المعلومات وممارساتها، وتتناول الأطر والعمليات والمنهجيات اللازمة للحوكمة الفعّالة لتقنية المعلومات في المؤسسات.']],
        'cobit-2019-foundation-isaca' => ['en' => 'COBIT 2019 Foundation – ISACA', 'ar' => 'أساسيات COBIT 2019 ‏(COBIT 2019 Foundation) – ISACA', 'days' => 3, 'summary' => ['en' => 'The COBIT 2019 Foundation course provides an introduction to the COBIT framework for the governance and management of enterprise IT.', 'ar' => 'تقدّم دورة COBIT 2019 Foundation مدخلاً إلى إطار COBIT لحوكمة تقنية المعلومات المؤسسية وإدارتها.']],
        'cobit-2019-implementer-isaca' => ['en' => 'COBIT 2019 Implementer – ISACA', 'ar' => 'شهادة COBIT 2019 Implementer – ISACA', 'days' => 3, 'summary' => ['en' => 'The COBIT 2019 Implementer course is designed to provide participants with the skills and knowledge needed to implement the COBIT 2019 framework within an organization.', 'ar' => 'صُمّمت دورة COBIT 2019 Implementer لتزويد المشاركين بالمهارات والمعارف اللازمة لتطبيق إطار COBIT 2019 داخل المؤسسة.']],
        'itil-4-strategist-direct-plan-and-improve-dpi-axelos' => ['en' => 'ITIL 4 Strategist: Direct, Plan, and Improve (DPI) – AXELOS', 'ar' => 'ITIL 4 Strategist: التوجيه والتخطيط والتحسين (DPI) – AXELOS', 'days' => 3, 'summary' => ['en' => 'The ITIL 4 Strategist: Direct, Plan, and Improve (DPI) course is designed to provide an in-depth understanding of how to direct, plan, and improve IT services and practices.', 'ar' => 'صُممت دورة ITIL 4 Strategist: التوجيه والتخطيط والتحسين (DPI) لتقديم فهم معمّق لكيفية توجيه خدمات تقنية المعلومات وممارساتها والتخطيط لها وتحسينها.']],
        'certified-in-risk-and-information-systems-control-crisc-isaca' => ['en' => 'Certified in Risk and Information Systems Control (CRISC) – ISACA', 'ar' => 'شهادة معتمد في إدارة المخاطر وضوابط نظم المعلومات (CRISC) – ISACA', 'days' => 5, 'summary' => ['en' => 'The CRISC certification course focuses on the principles and practices of risk management and information systems control.', 'ar' => 'تركّز دورة شهادة CRISC على مبادئ إدارة المخاطر وضوابط نظم المعلومات وممارساتها.']],
        'certified-information-security-manager-cism-isaca-it-governance' => ['en' => 'Certified Information Security Manager (CISM) – ISACA', 'ar' => 'شهادة مدير أمن المعلومات المعتمد (CISM) – ISACA', 'days' => 5, 'summary' => ['en' => 'The Certified Information Security Manager (CISM) course is designed to provide a comprehensive understanding of information security management and governance.', 'ar' => 'صُمّمت دورة مدير أمن المعلومات المعتمد (CISM) لتقديم فهم شامل لإدارة أمن المعلومات وحوكمته.']],
        'comptia-it-fundamentals-itf' => ['en' => 'CompTIA IT Fundamentals+ (ITF+)', 'ar' => 'أساسيات تقنية المعلومات CompTIA IT Fundamentals+ ‏(ITF+)', 'days' => 3, 'summary' => ['en' => 'The CompTIA IT Fundamentals+ (ITF+) course is designed to provide a broad understanding of IT concepts and fundamentals.', 'ar' => 'صُممت دورة CompTIA IT Fundamentals+ ‏(ITF+) لتقديم فهم واسع لمفاهيم تقنية المعلومات وأساسياتها، وهي موجهة إلى الأفراد الجدد في مجال تقنية المعلومات أو الذين يفكرون في بناء مسيرة مهنية فيه.']],
        'comptia-network' => ['en' => 'CompTIA Network+', 'ar' => 'شهادة CompTIA Network+', 'days' => 3, 'summary' => ['en' => 'The CompTIA Network+ certification course provides a thorough understanding of networking concepts and technologies.', 'ar' => 'تقدّم دورة شهادة CompTIA Network+ فهماً شاملاً لمفاهيم الشبكات وتقنياتها.']],
        'cisco-certified-network-associate-ccna' => ['en' => 'Cisco Certified Network Associate (CCNA)', 'ar' => 'شهادة Cisco Certified Network Associate ‏(CCNA)', 'days' => 5, 'summary' => ['en' => 'The Cisco Certified Network Associate (CCNA) course provides foundational knowledge and skills required to manage and operate small to medium-sized networks.', 'ar' => 'تقدّم دورة Cisco Certified Network Associate ‏(CCNA) المعارف والمهارات الأساسية اللازمة لإدارة الشبكات الصغيرة والمتوسطة الحجم وتشغيلها.']],
        'microsoft-certified-azure-fundamentals' => ['en' => 'Microsoft Certified: Azure Fundamentals', 'ar' => 'أساسيات Microsoft Azure ‏(Microsoft Certified: Azure Fundamentals)', 'days' => 3, 'summary' => ['en' => 'The Microsoft Certified: Azure Fundamentals course is designed to introduce individuals to the basic concepts of cloud services and how those concepts are implemented using Microsoft Azure.', 'ar' => 'صُممت دورة Microsoft Certified: Azure Fundamentals لتعريف الأفراد بالمفاهيم الأساسية للخدمات السحابية وكيفية تطبيق هذه المفاهيم باستخدام Microsoft Azure.']],
        'vmware-certified-professional-data-center-virtualization-vcp-dcv' => ['en' => 'VMware Certified Professional – Data Center Virtualization (VCP-DCV)', 'ar' => 'شهادة VMware Certified Professional – المحاكاة الافتراضية لمراكز البيانات (VCP-DCV)', 'days' => 5, 'summary' => ['en' => 'The VMware Certified Professional – Data Center Virtualization (VCP-DCV) course is designed to provide participants with the skills required to manage and deploy VMware vSphere environments.', 'ar' => 'صُمّمت دورة VMware Certified Professional – المحاكاة الافتراضية لمراكز البيانات (VCP-DCV) لتزويد المشاركين بالمهارات اللازمة لإدارة بيئات VMware vSphere ونشرها.']],
        'microsoft-certified-windows-server-hybrid-administrator-associate' => ['en' => 'Microsoft Certified: Windows Server Hybrid Administrator Associate', 'ar' => 'شهادة Microsoft Certified: مسؤول Windows Server الهجين المعتمد (Hybrid Administrator Associate)', 'days' => 5, 'summary' => ['en' => 'The Microsoft Certified: Windows Server Hybrid Administrator Associate course is designed to provide participants with the skills needed to manage and administer hybrid Windows Server environments.', 'ar' => 'صُممت دورة Microsoft Certified: Windows Server Hybrid Administrator Associate لتزويد المشاركين بالمهارات اللازمة لإدارة بيئات Windows Server الهجينة وتشغيلها.']],
        'itil-4-foundation-axelos' => ['en' => 'ITIL 4 Foundation – Axelos', 'ar' => 'أساسيات ITIL 4 ‏(ITIL 4 Foundation) – Axelos', 'days' => 3, 'summary' => ['en' => 'The ITIL 4 Foundation course provides a comprehensive introduction to ITIL 4, the latest version of the ITIL framework for IT service management.', 'ar' => 'تقدّم دورة ITIL 4 Foundation مقدمة شاملة إلى ITIL 4، أحدث إصدار من إطار عمل ITIL لإدارة خدمات تقنية المعلومات.']],
        'palo-alto-networks-certified-network-security-administrator-pcnsa' => ['en' => 'Palo Alto Networks Certified Network Security Administrator (PCNSA)', 'ar' => 'مسؤول أمن الشبكات المعتمد من Palo Alto Networks ‏(PCNSA)', 'days' => 5, 'summary' => ['en' => 'The Palo Alto Networks Certified Network Security Administrator (PCNSA) course provides foundational knowledge and skills necessary for the management of Palo Alto Networks next-generation firewalls.', 'ar' => 'تقدم دورة مسؤول أمن الشبكات المعتمد من Palo Alto Networks ‏(PCNSA) المعارف والمهارات الأساسية اللازمة لإدارة جدران الحماية من الجيل التالي (Next-Generation Firewalls) من Palo Alto Networks.']],
        'cisco-certified-devnet-associate-it-infrastructure' => ['en' => 'Cisco Certified DevNet Associate', 'ar' => 'شهادة Cisco Certified DevNet Associate', 'days' => 5, 'summary' => ['en' => 'The Cisco Certified DevNet Associate (DevNet Associate) course is designed to provide foundational knowledge and skills in software development and automation using Cisco technologies.', 'ar' => 'صُممت دورة Cisco Certified DevNet Associate ‏(DevNet Associate) لتزويد المشاركين بالمعارف والمهارات الأساسية في تطوير البرمجيات والأتمتة باستخدام تقنيات Cisco.']],
        'ec-council-ethical-hacking' => ['en' => 'EC-Council Ethical Hacking', 'ar' => 'شهادة الهاكر الأخلاقي المعتمد (CEH) – EC-Council', 'days' => 5, 'summary' => ['en' => 'This course meets the standards of highly skilled security professionals by providing a comprehensive set of ethical hacking and network security skills, tools and methodologies.', 'ar' => 'تلبّي هذه الدورة معايير المتخصصين في الأمن ذوي المهارات العالية، إذ تقدّم مجموعة شاملة من مهارات الاختراق الأخلاقي وأمن الشبكات وأدواتها ومنهجياتها.']],
        'introduction-to-cyber-security' => ['en' => 'Introduction to Cyber Security', 'ar' => 'مقدمة في الأمن السيبراني', 'days' => 3, 'summary' => ['en' => 'On this 3-day Cyber Security overview course, participants will be equipped with the knowledge and skills necessary to navigate the fascinating, yet complex, world of cyber security.', 'ar' => 'في هذه الدورة التعريفية بالأمن السيبراني ومدتها 3 أيام، سيكتسب المشاركون المعارف والمهارات اللازمة للتعامل مع عالم الأمن السيبراني المثير والمعقد في آنٍ معاً.']],
        'cloud-security-architecture' => ['en' => 'Cloud Security Architecture', 'ar' => 'بنية أمن الحوسبة السحابية', 'days' => 5, 'summary' => ['en' => 'Cloud computing is a new concept using old technologies.', 'ar' => 'الحوسبة السحابية مفهوم جديد يعتمد على تقنيات قديمة، وقد أصبحت سريعاً أداة حيوية في المؤسسات عبر جميع القطاعات بوصفها بنية تحتية للحوسبة على نطاق الإنترنت.']],
        'it-governance' => ['en' => 'IT Governance', 'ar' => 'حوكمة تقنية المعلومات', 'days' => 5, 'summary' => ['en' => 'This course explains how good IT Governance can help align IT strategies to business strategies.', 'ar' => 'توضح هذه الدورة كيف يمكن للحوكمة الجيدة لتقنية المعلومات أن تسهم في مواءمة استراتيجيات تقنية المعلومات مع استراتيجيات الأعمال، وذلك من خلال تناول حوكمة تقنية المعلومات على مستويين: حوكمة تقنية المعلومات، والحوكمة داخل تقنية المعلومات.']],
        'certificate-in-open-source-intelligence-osint-fundamentals' => ['en' => 'Certificate in Open-Source Intelligence (OSINT) Fundamentals', 'ar' => 'شهادة أساسيات استخبارات المصادر المفتوحة (OSINT)', 'days' => 3, 'summary' => ['en' => 'Open-Source Intelligence (OSINT) can provide organizations with an insight into their digital footprint by utilizing the Internet to determine if any part of their organization or staff members are exposed; and thereby expedite decision making as part of their risk management process.', 'ar' => 'يمكن لاستخبارات المصادر المفتوحة (OSINT) أن تزوّد المؤسسات برؤية واضحة عن بصمتها الرقمية، وذلك من خلال توظيف الإنترنت لتحديد ما إذا كان أي جزء من المؤسسة أو أيٌّ من موظفيها مكشوفاً، ومن ثَمّ تسريع عملية اتخاذ القرار ضمن منظومة إدارة المخاطر لديها.']],
        'certificate-in-information-security-management-principles-cismp' => ['en' => 'Certificate in Information Security Management Principles (CISMP)', 'ar' => 'شهادة مبادئ إدارة أمن المعلومات (CISMP)', 'days' => 5, 'summary' => ['en' => 'The BCS Foundation Certificate in Information Security Management Principles (CISMP) is an entry-level information security course that is non-technical in nature.', 'ar' => 'شهادة BCS التأسيسية في مبادئ إدارة أمن المعلومات (CISMP) هي دورة في أمن المعلومات للمستوى المبتدئ ذات طابع غير تقني.']],
        'certificate-in-it-management-processes-citmp' => ['en' => 'Certificate in IT Management Processes (CITMP)', 'ar' => 'شهادة عمليات إدارة تقنية المعلومات (CITMP)', 'days' => 5, 'summary' => ['en' => 'The omnipresence of information technology (IT) across an organization creates a scenario where an organization’s success depends on IT success.', 'ar' => 'إن الحضور الشامل لتقنية المعلومات (IT) في جميع أرجاء المؤسسة يخلق واقعاً يصبح فيه نجاح المؤسسة مرهوناً بنجاح تقنية المعلومات.']],
        'certified-cyber-security-specialist-ccss' => ['en' => 'Certified Cyber Security Specialist (CCSS)', 'ar' => 'أخصائي الأمن السيبراني المعتمد (CCSS)', 'days' => 5, 'summary' => ['en' => 'Participants on this Certified Cyber Security Specialist course will engage in an immersive learning experience that covers cybersecurity definitions, principles, practices, and industry standards.', 'ar' => 'سيخوض المشاركون في دورة أخصائي الأمن السيبراني المعتمد تجربة تعلّم غامرة تغطي تعريفات الأمن السيبراني ومبادئه وممارساته ومعايير القطاع.']],
        'certificate-in-it-disaster-recovery-planning-citdrp' => ['en' => 'Certificate in IT Disaster Recovery Planning (CITDRP)', 'ar' => 'شهادة تخطيط التعافي من كوارث تقنية المعلومات (CITDRP)', 'days' => 5, 'summary' => ['en' => 'This course provides participants with concrete solutions, strategies and insights into the delivery of an effective IT infrastructure and disaster recovery plan with the goal of establishing resilience measures to protect their organizations’ IT.', 'ar' => 'تزوّد هذه الدورة المشاركين بحلول واستراتيجيات ورؤى عملية لتنفيذ بنية تحتية فعّالة لتقنية المعلومات وخطة فعّالة للتعافي من الكوارث، بهدف إرساء تدابير المرونة اللازمة لحماية تقنية المعلومات في مؤسساتهم.']],
        'it-systems-identity-and-access-management' => ['en' => 'IT Systems: Identity and Access Management', 'ar' => 'أنظمة تقنية المعلومات: إدارة الهوية والوصول', 'days' => 5, 'summary' => ['en' => 'We are living in the age of the Internet of Things (IoT) which provides seamless integration and ease of access between various objects regardless of their physical proximity.', 'ar' => 'نعيش اليوم في عصر إنترنت الأشياء (IoT) الذي يتيح تكاملاً سلساً وسهولة في الوصول بين مختلف الأجهزة والكائنات بصرف النظر عن قربها المادي.']],
        'itil-4-managing-professional-itil-4-specialist-create-deliver-and-support-cds' => ['en' => 'ITIL 4 Managing Professional - ITIL 4 Specialist: Create, Deliver, and Support (CDS)', 'ar' => 'ITIL 4 Managing Professional – ITIL 4 Specialist: الإنشاء والتقديم والدعم (CDS)', 'days' => 3, 'summary' => ['en' => 'This course focuses on the core service management activities required to create, deliver, and support IT services.', 'ar' => 'تركّز هذه الدورة على الأنشطة الأساسية لإدارة الخدمات اللازمة لإنشاء خدمات تقنية المعلومات وتقديمها ودعمها.']],
        'itil-4-managing-professional-itil-4-specialist-drive-stakeholder-value-dsv' => ['en' => 'ITIL 4 Managing Professional - ITIL 4 Specialist: Drive Stakeholder Value (DSV)', 'ar' => 'ITIL 4 Managing Professional – ITIL 4 Specialist: تحقيق القيمة لأصحاب المصلحة (DSV)', 'days' => 3, 'summary' => ['en' => 'The ITIL DSV course focuses on the customer journey and interactions, ensuring that IT professionals understand how to engage stakeholders, improve customer satisfaction, and deliver valuable services.', 'ar' => 'تركّز دورة ITIL DSV على رحلة العميل والتفاعلات معه، بما يضمن فهم متخصصي تقنية المعلومات لكيفية إشراك أصحاب المصلحة، وتحسين رضا العملاء، وتقديم خدمات ذات قيمة.']],
        'itil-4-managing-professional-itil-4-specialist-high-velocity-it-hvit' => ['en' => 'ITIL 4 Managing Professional - ITIL 4 Specialist: High-Velocity IT (HVIT)', 'ar' => 'ITIL 4 Managing Professional – أخصائي ITIL 4: تقنية المعلومات عالية السرعة (HVIT)', 'days' => 3, 'summary' => ['en' => 'The HVIT course covers the use of IT in rapidly changing, high-velocity environments.', 'ar' => 'تتناول دورة HVIT استخدام تقنية المعلومات في البيئات سريعة التغير وعالية السرعة.']],
        'itil-4-managing-professional-itil-4-strategist-direct-plan-and-improve-dpi' => ['en' => 'ITIL 4 Managing Professional - ITIL 4 Strategist: Direct, Plan, and Improve (DPI)', 'ar' => 'ITIL 4 Strategist: التوجيه والتخطيط والتحسين (DPI) – AXELOS', 'days' => 3, 'summary' => ['en' => 'The ITIL 4 Strategist: Direct, Plan, and Improve (DPI) course is designed to provide an in-depth understanding of how to direct, plan, and improve IT services and practices.', 'ar' => 'صُممت دورة ITIL 4 Strategist: التوجيه والتخطيط والتحسين (DPI) لتقديم فهم معمّق لكيفية توجيه خدمات تقنية المعلومات وممارساتها والتخطيط لها وتحسينها.']],
